INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('KISW.G1.SARUFI.T10_VINYUME_VYA_VITENDO.a', 'KISW.G1.SARUFI.T10_VINYUME_VYA_VITENDO', 'a', 'kutambua vinyume vya vitendo mbalimbali katika kifungu chepesi', 'kicd_verified') ON CONFLICT (code) DO NOTHING;
