INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'KISW.G1.KUSIKI.T1_MAAMKUZI_NA_MAAGANO', 'kiswahili', 1, 'Tumia maamkuzi na maagano yafaayo na majibu yake', ARRAY['KISW.G1.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.a', 'KISW.G1.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.b']::text[], 'Chooses the greeting or farewell that fits who is met (a friend, an elder, a group), the time of day and whether arriving or leaving, and gives the right reply (Hujambo? Sijambo; Shikamoo, Marahaba; Hamjambo? Hatujambo), in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua salamu ifaayo","chagua jibu la salamu","igiza salamu (mwalimu anasikiliza)"]'::jsonb, '["recall","application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUSOMA.T1_USOMAJI_MWAFAKA.USOMAJI_MWAFAKA', 'KISW.G1.KUSOMA.T1_USOMAJI_MWAFAKA', 'kiswahili', 1, 'Keti vizuri, shika kitabu ipasavyo na usome kutoka kushoto kwenda kulia, juu hadi chini', ARRAY['KISW.G1.KUSOMA.T1_USOMAJI_MWAFAKA.a', 'KISW.G1.KUSOMA.T1_USOMAJI_MWAFAKA.b', 'KISW.G1.KUSOMA.T1_USOMAJI_MWAFAKA.c']::text[], 'Sits upright with the book on the desk at a fitting distance, holds it the right way up with the pages flat, and moves his eyes (and finger) from left to right and from the top line to the bottom, in 8 of 10 new items (the teacher also watches it in class).', '["chagua picha ya mkao bora","chagua mahali pa kuanzia kusoma","onyesha (mwalimu anaangalia)"]'::jsonb, '["application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUANDI.T1_UANDISHI_BORA.UANDISHI_BORA', 'KISW.G1.KUANDI.T1_UANDISHI_BORA', 'kiswahili', 1, 'Keti vizuri, shika kalamu ipasavyo na uandike kutoka kushoto kwenda kulia', ARRAY['KISW.G1.KUANDI.T1_UANDISHI_BORA.a', 'KISW.G1.KUANDI.T1_UANDISHI_BORA.b', 'KISW.G1.KUANDI.T1_UANDISHI_BORA.c', 'KISW.G1.KUANDI.T1_UANDISHI_BORA.d']::text[], 'Sits upright with both feet on the floor and the book straight, holds the pencil between thumb and two fingers without pressing hard, and writes from left to right along the line, in 8 of 10 new items (the teacher also watches it in class).', '["chagua picha ya mkao bora","chagua jinsi ya kushika kalamu","andika (mwalimu anaangalia)"]'::jsonb, '["application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.SARUFI.T1_MATUMIZI_YA_MIMI_NA_.NAFSI', 'KISW.G1.SARUFI.T1_MATUMIZI_YA_MIMI_NA_', 'kiswahili', 1, 'Tumia mimi na sisi ipasavyo katika sentensi', ARRAY['KISW.G1.SARUFI.T1_MATUMIZI_YA_MIMI_NA_.a', 'KISW.G1.SARUFI.T1_MATUMIZI_YA_MIMI_NA_.b']::text[], 'Uses mimi for himself and sisi for himself with others, with the matching subject marker (mimi ni-, sisi tu-), answers a question about himself with mimi, and puts -ni- inside the verb for "me" (alinipa), in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUSIKI.T2_MATAMSHI_BORA.MATAMSHI', 'KISW.G1.KUSIKI.T2_MATAMSHI_BORA', 'kiswahili', 1, 'Tambua na utamke silabi za sauti /m/, /a/, /u/, /k/, /t/, /l/ katika maneno na sentensi', ARRAY['KISW.G1.KUSIKI.T2_MATAMSHI_BORA.a', 'KISW.G1.KUSIKI.T2_MATAMSHI_BORA.b', 'KISW.G1.KUSIKI.T2_MATAMSHI_BORA.c', 'KISW.G1.KUSIKI.T2_MATAMSHI_BORA.d']::text[], 'Hears and says the target sounds /m/, /a/, /u/, /k/, /t/, /l/ in syllables and words (mama, kaka, tatu), splits a word into its syllables, and picks or uses a word that carries the sound, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno lenye sauti","gawa neno kwa silabi","chagua matamshi sahihi","tamka neno (mwalimu anasikiliza)"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G1.KUSOMA.T2_KUSOMA_KWA_UFASAHA', 'kiswahili', 1, 'Soma kifungu chepesi chenye sauti /m/, /a/, /u/, /k/, /t/, /l/ kwa matamshi bora, sauti inayosikika, kasi ifaayo na ishara', ARRAY['KISW.G1.KUSOMA.T2_KUSOMA_KWA_UFASAHA.a', 'KISW.G1.KUSOMA.T2_KUSOMA_KWA_UFASAHA.b', 'KISW.G1.KUSOMA.T2_KUSOMA_KWA_UFASAHA.c', 'KISW.G1.KUSOMA.T2_KUSOMA_KWA_UFASAHA.d']::text[], 'Finds the target sounds /m/, /a/, /u/, /k/, /t/, /l/ in a short story, reads it aloud with every sound clear, loud enough for the class, at about 5 words a minute, pausing at the koma and kikomo and raising the voice for a question; in the app picks the better reading of a line, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["tambua sauti lengwa","chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUANDI.T2_HATI_NADHIFU_HERUFI_.HATI_NADHIFU', 'KISW.G1.KUANDI.T2_HATI_NADHIFU_HERUFI_', 'kiswahili', 1, 'Andika kwa hati nadhifu ukitumia herufi kubwa ifaavyo', ARRAY['KISW.G1.KUANDI.T2_HATI_NADHIFU_HERUFI_.a', 'KISW.G1.KUANDI.T2_HATI_NADHIFU_HERUFI_.b']::text[], 'Writes a passage of about 5 words in neat handwriting: letters well formed and on the line, capitals only at the start of a sentence or name, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua maandishi nadhifu","tambua kosa","andika kifungu (mwalimu anasahihisha)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.SARUFI.T2_UMOJA_NA_WINGI_WA_MA.UMOJA_WINGI', 'KISW.G1.SARUFI.T2_UMOJA_NA_WINGI_WA_MA', 'kiswahili', 1, 'Taja na uandike majina ya vitu katika umoja na wingi', ARRAY['KISW.G1.SARUFI.T2_UMOJA_NA_WINGI_WA_MA.a', 'KISW.G1.SARUFI.T2_UMOJA_NA_WINGI_WA_MA.b']::text[], 'Names and writes things and people of his surroundings in singular and plural by their ngeli (mtoto - watoto, kiti - viti), keeping n-n nouns the same (kalamu - kalamu), in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUSIKI.T3_MANENO_YA_ADABU_NA_H.HESHIMA', 'KISW.G1.KUSIKI.T3_MANENO_YA_ADABU_NA_H', 'kiswahili', 1, 'Tumia maneno ya heshima na adabu: tafadhali, asante, samahani, pole, karibu', ARRAY['KISW.G1.KUSIKI.T3_MANENO_YA_ADABU_NA_H.a', 'KISW.G1.KUSIKI.T3_MANENO_YA_ADABU_NA_H.b']::text[], 'Picks and uses the polite word that fits the situation (tafadhali or naomba to ask, asante to thank, karibu to answer asante, samahani to apologise, pole to sympathise) and addresses an adult with a title, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno la adabu","kamilisha mazungumzo","igiza hali (mwalimu anasikiliza)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'KISW.G1.KUSOMA.T3_KUSOMA_KWA_UFAHAMU', 'kiswahili', 1, 'Soma kifungu chepesi: msamiati, ujumbe, kutabiri na mafunzo', ARRAY['KISW.G1.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.a', 'KISW.G1.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.b']::text[], 'Reads a very short passage on tarakimu and says what it is about, gives the meaning of a theme word from the sentence around it and says the message, answering from the passage and not from his own life, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua maana ya neno","chagua ujumbe","jibu swali kutoka kifungu"]'::jsonb, '["comprehension","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUANDI.T3_HATI_NADHIFU_HERUFI_.HATI_NADHIFU', 'KISW.G1.KUANDI.T3_HATI_NADHIFU_HERUFI_', 'kiswahili', 1, 'Andika kwa hati nadhifu ukitumia herufi ndogo ifaavyo', ARRAY['KISW.G1.KUANDI.T3_HATI_NADHIFU_HERUFI_.a', 'KISW.G1.KUANDI.T3_HATI_NADHIFU_HERUFI_.b']::text[], 'Writes a passage of about 5 words in neat handwriting: letters well formed and on the line, small letters of the right height, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua maandishi nadhifu","tambua kosa","andika kifungu (mwalimu anasahihisha)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.SARUFI.T3_MATUMIZI_YA_HUYU_NA_.VIONYESHI', 'KISW.G1.SARUFI.T3_MATUMIZI_YA_HUYU_NA_', 'kiswahili', 1, 'Tumia huyu na hawa ipasavyo kutokana na picha', ARRAY['KISW.G1.SARUFI.T3_MATUMIZI_YA_HUYU_NA_.a', 'KISW.G1.SARUFI.T3_MATUMIZI_YA_HUYU_NA_.b']::text[], 'Points at one person or animal near him with huyu and at many with hawa, and does not use huyu or hii for things, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.MATAMSHI', 'KISW.G1.KUSIKI.T4_MATAMSHI_BORA_SAUTI_', 'kiswahili', 1, 'Tambua na utamke silabi za sauti /n/, /o/, /w/, /e/, /i/, /h/ katika maneno na sentensi', ARRAY['KISW.G1.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.a', 'KISW.G1.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.b', 'KISW.G1.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.c', 'KISW.G1.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.d']::text[], 'Hears and says the target sounds /n/, /o/, /w/, /e/, /i/, /h/ in syllables and words (nane, wewe, hii), splits a word into its syllables, and picks or uses a word that carries the sound, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno lenye sauti","gawa neno kwa silabi","chagua matamshi sahihi","tamka neno (mwalimu anasikiliza)"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G1.KUSOMA.T4_KUSOMA_KWA_UFASAHA', 'kiswahili', 1, 'Soma kifungu chepesi chenye sauti /n/, /o/, /w/, /e/, /i/, /h/ kwa matamshi bora, sauti inayosikika, kasi ifaayo na ishara', ARRAY['KISW.G1.KUSOMA.T4_KUSOMA_KWA_UFASAHA.a', 'KISW.G1.KUSOMA.T4_KUSOMA_KWA_UFASAHA.b', 'KISW.G1.KUSOMA.T4_KUSOMA_KWA_UFASAHA.c', 'KISW.G1.KUSOMA.T4_KUSOMA_KWA_UFASAHA.d']::text[], 'Finds the target sounds /n/, /o/, /w/, /e/, /i/, /h/ in a short story, reads it aloud with every sound clear, loud enough for the class, at about 15 words a minute, pausing at the koma and kikomo and raising the voice for a question; in the app picks the better reading of a line, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["tambua sauti lengwa","chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUANDI.T4_HATI_NADHIFU.KUUNGANISHA_SILABI', 'KISW.G1.KUANDI.T4_HATI_NADHIFU', 'kiswahili', 1, 'Andika maneno kwa kuunganisha silabi bila nafasi kati ya herufi', ARRAY['KISW.G1.KUANDI.T4_HATI_NADHIFU.a', 'KISW.G1.KUANDI.T4_HATI_NADHIFU.b']::text[], 'Writes a word by joining its syllables (ma + ma = mama), with the letters of the word close together and no gap inside it, in the right order of syllables, in 8 of 10 new items (the teacher also checks it in the exercise book).', '["unganisha silabi","chagua neno lililoandikwa vizuri","andika neno (mwalimu anasahihisha)"]'::jsonb, '["application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.SARUFI.T4_UMOJA_NA_WINGI_WA_MA.UMOJA_WINGI', 'KISW.G1.SARUFI.T4_UMOJA_NA_WINGI_WA_MA', 'kiswahili', 1, 'Tumia majina ya ngeli za m-mi na li-ma katika umoja na wingi', ARRAY['KISW.G1.SARUFI.T4_UMOJA_NA_WINGI_WA_MA.a', 'KISW.G1.SARUFI.T4_UMOJA_NA_WINGI_WA_MA.b']::text[], 'Uses nouns of the m-mi and li-ma classes in singular and plural (mti - miti, yai - mayai, jicho - macho) when talking about his surroundings, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA', 'KISW.G1.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ', 'kiswahili', 1, 'Sikiliza kifungu, eleza ujumbe na msamiati wake, na usimulie upya', ARRAY['KISW.G1.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.a', 'KISW.G1.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.b', 'KISW.G1.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.c', 'KISW.G1.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.d']::text[], 'After hearing a short passage (Otieno alishiriki chakula chake na Kamau aliyesahau chakula), says its message, gives the meaning of a new word from it, uses the word in a sentence of his own and retells the events in order, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua ujumbe","chagua maana ya neno","panga matukio","simulia upya (mwalimu anasikiliza)"]'::jsonb, '["comprehension","sequencing"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUSOMA.T5_KUSOMA_KWA_UFAHAMU_K.UFAHAMU', 'KISW.G1.KUSOMA.T5_KUSOMA_KWA_UFAHAMU_K', 'kiswahili', 1, 'Soma kifungu chepesi: msamiati, ujumbe, kutabiri na mafunzo', ARRAY['KISW.G1.KUSOMA.T5_KUSOMA_KWA_UFAHAMU_K.a', 'KISW.G1.KUSOMA.T5_KUSOMA_KWA_UFAHAMU_K.b']::text[], 'Reads a very short passage on mimi na wenzangu and says what it is about, gives the meaning of a theme word from the sentence around it and says the message, answering from the passage and not from his own life, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua maana ya neno","chagua ujumbe","jibu swali kutoka kifungu"]'::jsonb, '["comprehension","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUANDI.T5_MATUMIZI_YA_KIKOMO.ALAMA', 'KISW.G1.KUANDI.T5_MATUMIZI_YA_KIKOMO', 'kiswahili', 1, 'Tumia kikomo na herufi kubwa ipasavyo katika maandishi', ARRAY['KISW.G1.KUANDI.T5_MATUMIZI_YA_KIKOMO.a', 'KISW.G1.KUANDI.T5_MATUMIZI_YA_KIKOMO.b', 'KISW.G1.KUANDI.T5_MATUMIZI_YA_KIKOMO.c']::text[], 'Tells a question from a statement, ends each with its mark (? or .), starts the next sentence with a capital, and writes a passage of about 5 words with the marks in place, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["weka alama sahihi","chagua sentensi iliyoakifishwa vizuri","andika kifungu (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.SARUFI.T5_MATUMIZI_YA_ANGU_NA_.VIMILIKISHI', 'KISW.G1.SARUFI.T5_MATUMIZI_YA_ANGU_NA_', 'kiswahili', 1, 'Tumia -angu na -etu ipasavyo', ARRAY['KISW.G1.SARUFI.T5_MATUMIZI_YA_ANGU_NA_.a', 'KISW.G1.SARUFI.T5_MATUMIZI_YA_ANGU_NA_.b']::text[], 'Uses -angu for what is his own and -etu for what he shares with others, with the prefix of the thing owned (kitabu changu, vitabu vyangu, darasa letu), after the noun, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI', 'KISW.G1.KUSIKI.T6_MATAMSHI_BORA', 'kiswahili', 1, 'Tambua na utamke silabi za sauti /s/, /b/, /y/, /z/, /g/, /d/ katika maneno na sentensi', ARRAY['KISW.G1.KUSIKI.T6_MATAMSHI_BORA.a', 'KISW.G1.KUSIKI.T6_MATAMSHI_BORA.b', 'KISW.G1.KUSIKI.T6_MATAMSHI_BORA.c', 'KISW.G1.KUSIKI.T6_MATAMSHI_BORA.d']::text[], 'Hears and says the target sounds /s/, /b/, /y/, /z/, /g/, /d/ in syllables and words (sikio, bega, damu), splits a word into its syllables, and picks or uses a word that carries the sound, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno lenye sauti","gawa neno kwa silabi","chagua matamshi sahihi","tamka neno (mwalimu anasikiliza)"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUSOMA.T6_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI', 'KISW.G1.KUSOMA.T6_KUSOMA_KWA_UFASAHA_S', 'kiswahili', 1, 'Soma kifungu chepesi chenye sauti /s/, /b/, /y/, /z/, /g/, /d/ kwa matamshi bora, sauti inayosikika, kasi ifaayo na ishara', ARRAY['KISW.G1.KUSOMA.T6_KUSOMA_KWA_UFASAHA_S.a', 'KISW.G1.KUSOMA.T6_KUSOMA_KWA_UFASAHA_S.b', 'KISW.G1.KUSOMA.T6_KUSOMA_KWA_UFASAHA_S.c', 'KISW.G1.KUSOMA.T6_KUSOMA_KWA_UFASAHA_S.d', 'KISW.G1.KUSOMA.T6_KUSOMA_KWA_UFASAHA_S.e', 'KISW.G1.KUSOMA.T6_KUSOMA_KWA_UFASAHA_S.f']::text[], 'Finds the target sounds /s/, /b/, /y/, /z/, /g/, /d/ in a short story, reads it aloud with every sound clear, loud enough for the class, at about 20 words a minute, pausing at the koma and kikomo and raising the voice for a question; in the app picks the better reading of a line, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["tambua sauti lengwa","chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUANDI.T6_TAHAJIA_IMLA.IMLA', 'KISW.G1.KUANDI.T6_TAHAJIA_IMLA', 'kiswahili', 1, 'Andika maneno yanayotamkwa kwenye imla kwa tahajia sahihi', ARRAY['KISW.G1.KUANDI.T6_TAHAJIA_IMLA.a', 'KISW.G1.KUANDI.T6_TAHAJIA_IMLA.b']::text[], 'Writes the words the teacher reads (about 5 words) with the right letters: the Kiswahili sound and not the home sound, the nasal kept (nd, mb, ng), long vowels doubled and ng'' with its apostrophe, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua tahajia sahihi","sahihisha neno","imla (mwalimu anasoma)"]'::jsonb, '["recall","application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.SARUFI.T6_MATUMIZI_YA_ZURI_NA_.VIVUMISHI', 'KISW.G1.SARUFI.T6_MATUMIZI_YA_ZURI_NA_', 'kiswahili', 1, 'Tumia -zuri na -baya ipasavyo katika sentensi', ARRAY['KISW.G1.SARUFI.T6_MATUMIZI_YA_ZURI_NA_.a', 'KISW.G1.SARUFI.T6_MATUMIZI_YA_ZURI_NA_.b']::text[], 'Uses -zuri and -baya after the noun with the right prefix (mtoto mzuri, kitabu kizuri, nguo nzuri, meno mabaya) and picks the one that matches the picture, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUSIKI.T7_MAAGIZO.MAAGIZO', 'KISW.G1.KUSIKI.T7_MAAGIZO', 'kiswahili', 1, 'Fuata na utoe maagizo mepesi kwa usahihi', ARRAY['KISW.G1.KUSIKI.T7_MAAGIZO.a', 'KISW.G1.KUSIKI.T7_MAAGIZO.b', 'KISW.G1.KUSIKI.T7_MAAGIZO.c']::text[], 'Follows a one- or two-step instruction in the right order, reads the direction and action words in it (simama, keti, kulia, kushoto, juu, chini), and gives a clear, polite instruction that names what to do and to what, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua kitendo sahihi","panga hatua","toa agizo (mwalimu anasikiliza)"]'::jsonb, '["comprehension","application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'KISW.G1.KUSOMA.T7_KUSOMA_KWA_UFAHAMU', 'kiswahili', 1, 'Soma kifungu chepesi: msamiati, ujumbe, kutabiri na mafunzo', ARRAY['KISW.G1.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.a', 'KISW.G1.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.b', 'KISW.G1.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.c', 'KISW.G1.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.d']::text[], 'Reads a short passage on usafi wa mwili, gives the meaning of a theme word from the sentence around it, says the message, predicts what happens next from the clues in the picture and says the lesson, answering from the passage and not from his own life, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua maana ya neno","chagua ujumbe","tabiri kitakachotokea","chagua funzo"]'::jsonb, '["comprehension","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUANDI.T7_KUANDIKA_MANENO_IPAS.TAHAJIA', 'KISW.G1.KUANDI.T7_KUANDIKA_MANENO_IPAS', 'kiswahili', 1, 'Andika maneno kwa tahajia sahihi', ARRAY['KISW.G1.KUANDI.T7_KUANDIKA_MANENO_IPAS.a', 'KISW.G1.KUANDI.T7_KUANDIKA_MANENO_IPAS.b']::text[], 'Writes the words of his own writing (about 5 words) with the right letters: the Kiswahili sound and not the home sound, the nasal kept (nd, mb, ng), long vowels doubled and ng'' with its apostrophe, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua tahajia sahihi","sahihisha neno","andika (mwalimu anasahihisha)"]'::jsonb, '["recall","application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.SARUFI.T7_UKANUSHAJI.UKANUSHAJI', 'KISW.G1.SARUFI.T7_UKANUSHAJI', 'kiswahili', 1, 'Kanusha sentensi za nafsi ya kwanza umoja na wingi', ARRAY['KISW.G1.SARUFI.T7_UKANUSHAJI.a', 'KISW.G1.SARUFI.T7_UKANUSHAJI.b']::text[], 'Makes the negative of a present-tense sentence in the first person: mimi ninaoga - mimi siogi, sisi tunaoga - sisi hatuogi (si-/hatu-, no -na-, final -a to -i), in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI', 'KISW.G1.KUSIKI.T8_MATAMSHI_BORA', 'kiswahili', 1, 'Tambua na utamke silabi za sauti /j/, /r/, /p/, /f/, /v/, /sh/ katika maneno na sentensi', ARRAY['KISW.G1.KUSIKI.T8_MATAMSHI_BORA.a', 'KISW.G1.KUSIKI.T8_MATAMSHI_BORA.b', 'KISW.G1.KUSIKI.T8_MATAMSHI_BORA.c', 'KISW.G1.KUSIKI.T8_MATAMSHI_BORA.d']::text[], 'Hears and says the target sounds /j/, /r/, /p/, /f/, /v/, /sh/ in syllables and words (viazi, papai, shamba), splits a word into its syllables, and picks or uses a word that carries the sound, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno lenye sauti","gawa neno kwa silabi","chagua matamshi sahihi","tamka neno (mwalimu anasikiliza)"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G1.KUSOMA.T8_KUSOMA_KWA_UFASAHA', 'kiswahili', 1, 'Soma kifungu chepesi chenye sauti /j/, /r/, /p/, /f/, /v/, /sh/ kwa matamshi bora, sauti inayosikika, kasi ifaayo na ishara', ARRAY['KISW.G1.KUSOMA.T8_KUSOMA_KWA_UFASAHA.a', 'KISW.G1.KUSOMA.T8_KUSOMA_KWA_UFASAHA.b', 'KISW.G1.KUSOMA.T8_KUSOMA_KWA_UFASAHA.c', 'KISW.G1.KUSOMA.T8_KUSOMA_KWA_UFASAHA.d', 'KISW.G1.KUSOMA.T8_KUSOMA_KWA_UFASAHA.e']::text[], 'Finds the target sounds /j/, /r/, /p/, /f/, /v/, /sh/ in a short story, reads it aloud with every sound clear, loud enough for the class, at about 25 words a minute, pausing at the koma and kikomo and raising the voice for a question; in the app picks the better reading of a line, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["tambua sauti lengwa","chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUANDI.T8_TAHAJIA.TAHAJIA', 'KISW.G1.KUANDI.T8_TAHAJIA', 'kiswahili', 1, 'Andika insha fupi kwa tahajia sahihi za maneno', ARRAY['KISW.G1.KUANDI.T8_TAHAJIA.a', 'KISW.G1.KUANDI.T8_TAHAJIA.b']::text[], 'Writes the words of his own writing (about 10 words) with the right letters: the Kiswahili sound and not the home sound, the nasal kept (nd, mb, ng), long vowels doubled and ng'' with its apostrophe, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua tahajia sahihi","sahihisha neno","andika (mwalimu anasahihisha)"]'::jsonb, '["recall","application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.SARUFI.T8_MATUMIZI_YA_HIKI_NA_.VIONYESHI', 'KISW.G1.SARUFI.T8_MATUMIZI_YA_HIKI_NA_', 'kiswahili', 1, 'Tumia hiki na hivi kuonyeshea vitu', ARRAY['KISW.G1.SARUFI.T8_MATUMIZI_YA_HIKI_NA_.a', 'KISW.G1.SARUFI.T8_MATUMIZI_YA_HIKI_NA_.b', 'KISW.G1.SARUFI.T8_MATUMIZI_YA_HIKI_NA_.c']::text[], 'Points at one ki-vi thing near him with hiki and at many with hivi (chakula hiki - vyakula hivi, kiazi hiki - viazi hivi), not huyu or hii, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUSIKI.T9_MAZUNGUMZO.MAZUNGUMZO', 'KISW.G1.KUSIKI.T9_MAZUNGUMZO', 'kiswahili', 1, 'Shiriki mazungumzo kuhusu vyombo vya jikoni kwa zamu, kwa matamshi bora na ishara zifaazo', ARRAY['KISW.G1.KUSIKI.T9_MAZUNGUMZO.a', 'KISW.G1.KUSIKI.T9_MAZUNGUMZO.b', 'KISW.G1.KUSIKI.T9_MAZUNGUMZO.c']::text[], 'Takes part in a short conversation about vyombo vya jikoni: keeps to the topic, waits for his turn, speaks Kiswahili without English or Sheng words, says sounds clearly and uses gestures that match the words, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua jibu linalofaa mada","tambua kosa la mazungumzo","zungumza (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'KISW.G1.KUSOMA.T9_KUSOMA_KWA_UFAHAMU', 'kiswahili', 1, 'Soma kifungu chepesi: msamiati, ujumbe, kutabiri na mafunzo', ARRAY['KISW.G1.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.a', 'KISW.G1.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.b', 'KISW.G1.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.c', 'KISW.G1.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.d']::text[], 'Reads a short passage on jikoni, gives the meaning of a theme word from the sentence around it, says the message, predicts what happens next from the clues in the picture and says the lesson, answering from the passage and not from his own life, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua maana ya neno","chagua ujumbe","tabiri kitakachotokea","chagua funzo"]'::jsonb, '["comprehension","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUANDI.T9_KIFUNGU_KUTOKANA_NA_.KIFUNGU', 'KISW.G1.KUANDI.T9_KIFUNGU_KUTOKANA_NA_', 'kiswahili', 1, 'Andika kifungu kifupi kutokana na picha', ARRAY['KISW.G1.KUANDI.T9_KIFUNGU_KUTOKANA_NA_.a', 'KISW.G1.KUANDI.T9_KIFUNGU_KUTOKANA_NA_.b']::text[], 'Writes a short paragraph about a picture on jikoni: a title that fits, sentences in order, one tense, Kiswahili words only, capitals and kikomo in place, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua kichwa kifaacho","panga sentensi","tambua kosa","andika (mwalimu anasahihisha)"]'::jsonb, '["application","sequencing"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.SARUFI.T9_MATUMIZI_YA_MANENO_Y.VITENDO', 'KISW.G1.SARUFI.T9_MATUMIZI_YA_MANENO_Y', 'kiswahili', 1, 'Tambua na utumie maneno yanayoashiria vitendo', ARRAY['KISW.G1.SARUFI.T9_MATUMIZI_YA_MANENO_Y.a', 'KISW.G1.SARUFI.T9_MATUMIZI_YA_MANENO_Y.b', 'KISW.G1.SARUFI.T9_MATUMIZI_YA_MANENO_Y.c']::text[], 'Finds the action word in a short sentence (Mama anapika ugali: anapika), reads it, and uses an action word with the right person marker (mama anapika, watoto wanakula), in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["tambua neno la kitendo","jaza pengo kwa kitendo","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI', 'KISW.G1.KUSIKI.T10_MATAMSHI_BORA', 'kiswahili', 1, 'Tambua na utamke silabi za sauti /ny/, /dh/, /th/, /ch/, /gh/, /ng/, /ng''/ katika maneno na sentensi', ARRAY['KISW.G1.KUSIKI.T10_MATAMSHI_BORA.a', 'KISW.G1.KUSIKI.T10_MATAMSHI_BORA.b', 'KISW.G1.KUSIKI.T10_MATAMSHI_BORA.c', 'KISW.G1.KUSIKI.T10_MATAMSHI_BORA.d']::text[], 'Hears and says the target sounds /ny/, /dh/, /th/, /ch/, /gh/, /ng/, /ng''/ in syllables and words (ngoma, chenga, nyota), splits a word into its syllables, and picks or uses a word that carries the sound, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno lenye sauti","gawa neno kwa silabi","chagua matamshi sahihi","tamka neno (mwalimu anasikiliza)"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G1.KUSOMA.T10_KUSOMA_KWA_UFASAHA', 'kiswahili', 1, 'Soma kifungu chepesi chenye sauti /ny/, /dh/, /th/, /ch/, /gh/, /ng/, /ng''/ kwa matamshi bora, sauti inayosikika, kasi ifaayo na ishara', ARRAY['KISW.G1.KUSOMA.T10_KUSOMA_KWA_UFASAHA.a', 'KISW.G1.KUSOMA.T10_KUSOMA_KWA_UFASAHA.b', 'KISW.G1.KUSOMA.T10_KUSOMA_KWA_UFASAHA.c', 'KISW.G1.KUSOMA.T10_KUSOMA_KWA_UFASAHA.d', 'KISW.G1.KUSOMA.T10_KUSOMA_KWA_UFASAHA.e']::text[], 'Finds the target sounds /ny/, /dh/, /th/, /ch/, /gh/, /ng/, /ng''/ in a short story, reads it aloud with every sound clear, loud enough for the class, at about 30 words a minute, pausing at the koma and kikomo and raising the voice for a question; in the app picks the better reading of a line, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["tambua sauti lengwa","chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.KUANDI.T10_KIFUNGU_KUTOKANA_NA_.KIFUNGU', 'KISW.G1.KUANDI.T10_KIFUNGU_KUTOKANA_NA_', 'kiswahili', 1, 'Andika kifungu kifupi kutokana na picha', ARRAY['KISW.G1.KUANDI.T10_KIFUNGU_KUTOKANA_NA_.a', 'KISW.G1.KUANDI.T10_KIFUNGU_KUTOKANA_NA_.b']::text[], 'Writes a short paragraph about a picture on michezo: a title that fits, sentences in order, one tense, Kiswahili words only, capitals and kikomo in place, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua kichwa kifaacho","panga sentensi","tambua kosa","andika (mwalimu anasahihisha)"]'::jsonb, '["application","sequencing"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G1.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME', 'KISW.G1.SARUFI.T10_VINYUME_VYA_VITENDO', 'kiswahili', 1, 'Tambua na utumie vinyume vya vitendo', ARRAY['KISW.G1.SARUFI.T10_VINYUME_VYA_VITENDO.a', 'KISW.G1.SARUFI.T10_VINYUME_VYA_VITENDO.b']::text[], 'Gives the opposite action of a simple verb (anza - maliza, keti - simama, ingia - toka, panda - shuka), not its negative, a word of the same meaning or a place word, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
