INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('KISW.G1.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME', 'KISW.G1.SARUFI.T7_UKANUSHAJI.UKANUSHAJI', 'skill', 'helpful', 'Knowing the negative lets the child tell it from the opposite.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M1_SAL_REPLY_T1', 'KISW.G1.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Answers a greeting with the same greeting (Hujambo? Hujambo!) instead of its reply.', '{"question":"Rafiki anakusalimu: \"Hujambo?\" Unajibu nini?","wrong_answer":"Hujambo","correct_answer":"Sijambo"}'::jsonb, 'The child hears the greeting as a sound to echo, as with "Hello" in English; the question-and-answer pair has not been learnt.', 'The question "Rafiki anakusalimu: "Hujambo?" Unajibu nini?" with "Hujambo" among the options.', 'Act it as a ball game: the greeting is thrown, the reply is caught; the two words are on two different cards.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M1_SAL_ELDER_T1', 'KISW.G1.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Greets an elder with a peer or Sheng greeting (Mambo! Sasa!) instead of Shikamoo.', '{"question":"Unamwona babu njiani. Unamsalimu vipi?","wrong_answer":"Mambo babu!","correct_answer":"Shikamoo babu!"}'::jsonb, 'Mambo and Sasa are what the child hears most among children and on the street; he has not been taught that an elder is greeted differently.', 'The question "Unamwona babu njiani. Unamsalimu vipi?" with "Mambo babu!" among the options.', 'Sort picture cards of people (babu, rafiki, mwalimu) into two piles: Shikamoo and Hujambo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M1_SAL_MARAHABA_T1', 'KISW.G1.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Gives the elder''s reply to the child''s greeting the wrong way round (the elder says Shikamoo, or the child says Marahaba).', '{"question":"Mtoto anamsalimu bibi: \"Shikamoo bibi!\" Bibi anajibu nini?","wrong_answer":"Shikamoo","correct_answer":"Marahaba"}'::jsonb, 'Both words are heard together and the child does not yet know which belongs to the young person and which to the elder.', 'The question "Mtoto anamsalimu bibi: "Shikamoo bibi!" Bibi anajibu nini?" with "Shikamoo" among the options.', 'Role-play with a hat for the elder: only the one with the hat may say Marahaba.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M1_SAL_TIME_T1', 'KISW.G1.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Uses the greeting of another time of day.', '{"question":"Unamwona mwalimu asubuhi. Unamsalimu vipi?","wrong_answer":"Habari za jioni mwalimu!","correct_answer":"Habari za asubuhi mwalimu!"}'::jsonb, 'The child learnt one greeting as a set phrase and uses it at every hour.', 'The question "Unamwona mwalimu asubuhi. Unamsalimu vipi?" with "Habari za jioni mwalimu!" among the options.', 'A clock or sun chart: asubuhi, mchana, jioni, usiku; the child moves the arrow and says the greeting for that time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M1_SAL_LEAVE_T1', 'KISW.G1.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Uses a greeting when leaving, or a farewell when arriving.', '{"question":"Unaenda nyumbani baada ya shule. Unamuaga mwalimu vipi?","wrong_answer":"Hujambo mwalimu!","correct_answer":"Kwaheri mwalimu!"}'::jsonb, 'Greeting and farewell words are learnt on one chart and the child mixes the two columns.', 'The question "Unaenda nyumbani baada ya shule. Unamuaga mwalimu vipi?" with "Hujambo mwalimu!" among the options.', 'Act out a door: walk in and greet, walk out and say goodbye.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M1_SAL_GROUP_T1', 'KISW.G1.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Greets a group with the singular greeting (Hujambo?) or answers for a group with Sijambo.', '{"question":"Mwalimu anaingia darasani na kusema: \"Hamjambo wanafunzi?\" Darasa linajibu nini?","wrong_answer":"Sijambo","correct_answer":"Hatujambo"}'::jsonb, 'The child knows one pair only; the plural forms hamjambo/hatujambo follow the person marker (m-, tu-), which has not been noticed.', 'The question "Mwalimu anaingia darasani na kusema: "Hamjambo wanafunzi?" Darasa linajibu nini?" with "Sijambo" among the options.', 'Greet one child, then the whole row; show that the word changes with one or many.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T1_USOMAJI_MWAFAKA.USOMAJI_MWAFAKA.M1_USM_RIGHT_T1', 'KISW.G1.KUSOMA.T1_USOMAJI_MWAFAKA.USOMAJI_MWAFAKA', 'Starts reading from the right or from the bottom of the page.', '{"question":"Unaanza kusoma ukurasa kutoka wapi?","wrong_answer":"chini upande wa kulia","correct_answer":"juu upande wa kushoto"}'::jsonb, 'Some children have seen other scripts read from the right, or simply start where the picture is.', 'The question "Unaanza kusoma ukurasa kutoka wapi?" with "chini upande wa kulia" among the options.', 'Put a green dot at the top left of each page: start at the green dot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T1_USOMAJI_MWAFAKA.USOMAJI_MWAFAKA.M1_USM_UPSIDE_T1', 'KISW.G1.KUSOMA.T1_USOMAJI_MWAFAKA.USOMAJI_MWAFAKA', 'Holds the book upside down or back to front.', '{"question":"Kitabu kiko sawa lini?","wrong_answer":"picha zikiwa juu chini","correct_answer":"picha na maandishi yakiwa wima, jalada mbele"}'::jsonb, 'The child has handled few books and does not check the picture before reading.', 'The question "Kitabu kiko sawa lini?" with "picha zikiwa juu chini" among the options.', 'Before opening, find the front cover and check that the people in the picture stand up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T1_USOMAJI_MWAFAKA.USOMAJI_MWAFAKA.M1_USM_POSTURE_T1', 'KISW.G1.KUSOMA.T1_USOMAJI_MWAFAKA.USOMAJI_MWAFAKA', 'Reads lying on the desk with his face almost on the page, or leaning back far from it.', '{"question":"Mkao upi ni bora unaposoma?","wrong_answer":"kulala juu ya meza uso karibu na kitabu","correct_answer":"kuketi wima, kitabu mezani umbali wa mkono"}'::jsonb, 'The child is tired or cannot see well; nobody has shown the reading position.', 'The question "Mkao upi ni bora unaposoma?" with "kulala juu ya meza uso karibu na kitabu" among the options.', 'Show the "elbow distance": the book is as far as from the elbow to the hand. If the child still leans in, tell the parent to check the eyes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T1_USOMAJI_MWAFAKA.USOMAJI_MWAFAKA.M1_USM_SKIPLINE_T1', 'KISW.G1.KUSOMA.T1_USOMAJI_MWAFAKA.USOMAJI_MWAFAKA', 'Loses the line and jumps to another line or back to the start.', '{"question":"Unapomaliza mstari wa kwanza, unaenda wapi?","wrong_answer":"popote ninapoona neno ninalolijua","correct_answer":"mwanzo wa mstari wa pili, upande wa kushoto"}'::jsonb, 'The eye sweep back to the next line is new; without a finger guide the child lands anywhere.', 'The question "Unapomaliza mstari wa kwanza, unaenda wapi?" with "popote ninapoona neno ninalolijua" among the options.', 'Move a finger or a card under the line; at the end, slide back to the left and down one line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T1_UANDISHI_BORA.UANDISHI_BORA.M1_UAN_FIST_T1', 'KISW.G1.KUANDI.T1_UANDISHI_BORA.UANDISHI_BORA', 'Grips the pencil in the fist, or with all the fingers wrapped round it.', '{"question":"Kalamu inashikwa vipi?","wrong_answer":"kwa ngumi nzima","correct_answer":"kwa kidole gumba na vidole viwili"}'::jsonb, 'A fist grip is how small children first hold a crayon; the tripod grip has not been taught.', 'The question "Kalamu inashikwa vipi?" with "kwa ngumi nzima" among the options.', 'Pinch the pencil with thumb and pointer, rest it on the middle finger; a small rubber band can mark the place.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T1_UANDISHI_BORA.UANDISHI_BORA.M1_UAN_SLUMP_T1', 'KISW.G1.KUANDI.T1_UANDISHI_BORA.UANDISHI_BORA', 'Writes with the head on the desk or the body twisted, the book at an angle.', '{"question":"Mkao upi ni bora unapoandika?","wrong_answer":"kichwa juu ya meza","correct_answer":"kuketi wima, miguu sakafuni, daftari limenyooka"}'::jsonb, 'The child tires quickly and nobody has shown the writing position.', 'The question "Mkao upi ni bora unapoandika?" with "kichwa juu ya meza" among the options.', 'Check four things before writing: back straight, feet down, book straight, free hand holding the page.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T1_UANDISHI_BORA.UANDISHI_BORA.M1_UAN_RTL_T1', 'KISW.G1.KUANDI.T1_UANDISHI_BORA.UANDISHI_BORA', 'Starts writing at the right of the line, or writes letters from right to left.', '{"question":"Unaanza kuandika mstari kutoka wapi?","wrong_answer":"upande wa kulia","correct_answer":"upande wa kushoto"}'::jsonb, 'The child starts wherever there is space, or copies the direction of a sibling''s writing in another script.', 'The question "Unaanza kuandika mstari kutoka wapi?" with "upande wa kulia" among the options.', 'A green start line at the left margin of each line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T1_UANDISHI_BORA.UANDISHI_BORA.M1_UAN_PRESS_T1', 'KISW.G1.KUANDI.T1_UANDISHI_BORA.UANDISHI_BORA', 'Presses so hard the pencil breaks or tears the page.', '{"question":"Unaandika kwa nguvu kiasi gani?","wrong_answer":"kwa nguvu sana mpaka karatasi ikatike","correct_answer":"kwa upole, kalamu ikiteleza"}'::jsonb, 'The child holds the pencil too tight from worry or from the fist grip.', 'The question "Unaandika kwa nguvu kiasi gani?" with "kwa nguvu sana mpaka karatasi ikatike" among the options.', 'Write on a sheet with carbon or soft paper below; the mark should not come through.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T1_MATUMIZI_YA_MIMI_NA_.NAFSI.M1_SAR_PREFIX_T1', 'KISW.G1.SARUFI.T1_MATUMIZI_YA_MIMI_NA_.NAFSI', 'The pronoun and the subject marker on the verb do not agree (Wao anacheza).', '{"question":"Jaza: Sisi ___ (imba) wimbo.","wrong_answer":"ninaimba","correct_answer":"tunaimba"}'::jsonb, 'The child learns the pronoun as a word and the verb as a fixed form; he has not seen that the verb changes with the person.', 'The question "Jaza: Sisi ___ (imba) wimbo." with "ninaimba" among the options.', 'Colour the pronoun and the verb''s first syllable the same colour: yeye a-, wao wa-, mimi ni-, sisi tu-, wewe u-, nyinyi m-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T1_MATUMIZI_YA_MIMI_NA_.NAFSI.M1_SAR_NUMBER_T1', 'KISW.G1.SARUFI.T1_MATUMIZI_YA_MIMI_NA_.NAFSI', 'Uses the one-person pronoun for many people, or the reverse.', '{"question":"Mimi na Ali tunacheza. ___ tunacheza.","wrong_answer":"Mimi","correct_answer":"Sisi"}'::jsonb, 'The child has not linked the pronoun pair to one and many.', 'The question "Mimi na Ali tunacheza. ___ tunacheza." with "Mimi" among the options.', 'Point at one child, then at a group, saying the right pronoun each time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T1_MATUMIZI_YA_MIMI_NA_.NAFSI.M1_SAR_PERSON_T1', 'KISW.G1.SARUFI.T1_MATUMIZI_YA_MIMI_NA_.NAFSI', 'Repeats the pronoun of the question in the answer (Wewe unaenda wapi? Wewe ninaenda sokoni.) instead of switching to mimi.', '{"question":"Mwalimu anakuuliza: \"Unaitwa nani?\" Unajibu:","wrong_answer":"Wewe ni Baraka.","correct_answer":"Mimi ni Baraka."}'::jsonb, 'The child copies the words he heard; changing person between speakers is new.', 'The question "Mwalimu anakuuliza: "Unaitwa nani?" Unajibu:" with "Wewe ni Baraka." among the options.', 'Ask and answer in pairs with a pointing finger: wewe points out, mimi points to the chest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T1_MATUMIZI_YA_MIMI_NA_.NAFSI.M1_SAR_OBJ_T1', 'KISW.G1.SARUFI.T1_MATUMIZI_YA_MIMI_NA_.NAFSI', 'Puts the pronoun after the verb instead of the object marker inside it (Mama alimpa mimi for Mama alinipa).', '{"question":"Ni lipi sahihi?","wrong_answer":"Mama alimpa mimi chakula.","correct_answer":"Mama alinipa chakula."}'::jsonb, 'English says "gave me"; the child adds the separate word instead of -ni- inside the verb.', 'The question "Ni lipi sahihi?" with "Mama alimpa mimi chakula." among the options.', 'Show the verb with the object marker coloured: a-li-ni-pa; compare with the wrong form.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T2_MATAMSHI_BORA.MATAMSHI.M1_SAU_NEAR_T2', 'KISW.G1.KUSIKI.T2_MATAMSHI_BORA.MATAMSHI', 'Says /r/ for /l/, so "lala" becomes "rara".', '{"question":"Mwalimu anasema \"lala\". Neno lipi limetamkwa vizuri?","wrong_answer":"rara","correct_answer":"lala"}'::jsonb, 'Many Kenyan first languages have no /l/, or do not separate it from /r/; the child puts in the home sound.', 'The question "Mwalimu anasema "lala". Neno lipi limetamkwa vizuri?" with "rara" among the options.', 'Say the two side by side, slowly, watching the mouth; the child holds up a card for the sound he hears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T2_MATAMSHI_BORA.MATAMSHI.M1_SAU_NEAR2_T2', 'KISW.G1.KUSIKI.T2_MATAMSHI_BORA.MATAMSHI', 'Says /g/ for /k/, so "kaka" becomes "gaga".', '{"question":"Neno lipi limetamkwa vizuri?","wrong_answer":"gaga","correct_answer":"kaka"}'::jsonb, '/k/ and /g/ are close; a first language with only one of them puts that one in both places.', 'The question "Neno lipi limetamkwa vizuri?" with "gaga" among the options.', 'Contrast the two with a mirror and a hand before the mouth; the child says which he hears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T2_MATAMSHI_BORA.MATAMSHI.M1_SAU_SYLL_T2', 'KISW.G1.KUSIKI.T2_MATAMSHI_BORA.MATAMSHI', 'Splits "mama" by letters rather than by syllables (each Kiswahili syllable ends in a vowel).', '{"question":"Neno \"mama\" lina silabi zipi?","wrong_answer":"m-a-m-a","correct_answer":"ma-ma"}'::jsonb, 'The child has learnt letters one by one and has not been shown that a syllable is a sound that ends in a vowel.', 'The question "Neno "mama" lina silabi zipi?" with "m-a-m-a" among the options.', 'Clap the word: one clap per vowel; the consonants go with the vowel after them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T2_MATAMSHI_BORA.MATAMSHI.M1_SAU_NAME_T2', 'KISW.G1.KUSIKI.T2_MATAMSHI_BORA.MATAMSHI', 'Says the English letter name instead of the Kiswahili sound (/m/ as "em"), so the syllable cannot be built.', '{"question":"Sauti ya herufi \"m\" ni ipi?","wrong_answer":"em","correct_answer":"/m/"}'::jsonb, 'English letter names are taught alongside and the child brings them to Kiswahili; a syllable is built from sounds, not names.', 'The question "Sauti ya herufi "m" ni ipi?" with "em" among the options.', 'Say the sound alone, short (/m/), then join it to a vowel: ma, me, mi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T2_MATAMSHI_BORA.MATAMSHI.M1_SAU_PICK_T2', 'KISW.G1.KUSIKI.T2_MATAMSHI_BORA.MATAMSHI', 'Picks a word with no target sound when asked for one that has it.', '{"question":"Ni neno lipi lina sauti /m/, /a/, /u/, /k/, /t/, /l/?","wrong_answer":"baba","correct_answer":"kaka"}'::jsonb, 'The child looks at the first letter or the picture, not at the sound.', 'The question "Ni neno lipi lina sauti /m/, /a/, /u/, /k/, /t/, /l/?" with "baba" among the options.', 'Underline the target sound in each word on the card before choosing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M1_UFS_SOUND_T2', 'KISW.G1.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads the target word wrongly: "kuku" as "guku".', '{"question":"Neno \"kuku\" linasomwa vipi?","wrong_answer":"guku","correct_answer":"kuku"}'::jsonb, 'The child reads the letters with the sounds of his first language, or adds a vowel to break the cluster.', 'The question "Neno "kuku" linasomwa vipi?" with "guku" among the options.', 'Pick out the target words before reading; practise them on cards, then read the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M1_UFS_WORD_T2', 'KISW.G1.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Mama ana kuku.\"?","wrong_answer":"Mama ... ana ... kuku.","correct_answer":"Mama ana kuku."}'::jsonb, 'The child is still decoding each word; he has not yet read a group of words as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Mama ana kuku."?" with "Mama ... ana ... kuku." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it in one breath.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M1_UFS_QUIET_T2', 'KISW.G1.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads so softly (or so loudly, shouting) that the class cannot follow.', '{"question":"Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?","wrong_answer":"ya chini ili nisikosee mbele ya wenzangu","correct_answer":"ya kusikika na wote darasani, bila kupiga kelele"}'::jsonb, 'Shyness, or the belief that reading well means reading loud.', 'The question "Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?" with "ya chini ili nisikosee mbele ya wenzangu" among the options.', 'Stand the reader at the front and a listener at the back: the listener raises a hand when he hears every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M1_UFS_PACE_T2', 'KISW.G1.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Kasi ifaayo ya kusoma kifungu ni ipi?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, karibu maneno 5 kwa dakika"}'::jsonb, 'Reading races in class reward speed; nobody asked whether the listeners understood.', 'The question "Kasi ifaayo ya kusoma kifungu ni ipi?" with "haraka iwezekanavyo" among the options.', 'Time two readings, one very fast and one at speaking pace; the listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M1_UFS_MARK_T2', 'KISW.G1.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question in the flat voice of a statement and runs on through the koma and kikomo.', '{"question":"Sentensi \"Je, kaka yuko?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the marks.', 'The question "Sentensi "Je, kaka yuko?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that fits each reading; clap at each kikomo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T2_HATI_NADHIFU_HERUFI_.HATI_NADHIFU.M1_HAT_CAPSTART_T2', 'KISW.G1.KUANDI.T2_HATI_NADHIFU_HERUFI_.HATI_NADHIFU', 'Starts a sentence or a name with a small letter.', '{"question":"Andika kwa usahihi: mama na baba wako nyumbani.","wrong_answer":"mama na baba wako nyumbani.","correct_answer":"Mama na Baba wako nyumbani."}'::jsonb, 'The child copies words, not sentences; the rule that a sentence and a name begin with a capital is not yet used.', 'The question "Andika kwa usahihi: mama na baba wako nyumbani." with "mama na baba wako nyumbani." among the options.', 'Circle the first letter of each sentence and each name in a passage in red.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T2_HATI_NADHIFU_HERUFI_.HATI_NADHIFU.M1_HAT_CAPMID_T2', 'KISW.G1.KUANDI.T2_HATI_NADHIFU_HERUFI_.HATI_NADHIFU', 'Puts capital letters in the middle of words (JuMa, Kitabu KiKubwa).', '{"question":"Ni lipi limeandikwa vizuri?","wrong_answer":"JuMa ANakula","correct_answer":"Juma anakula"}'::jsonb, 'Some capitals (K, M, S) are easier to form than the small letter, so the child uses them anywhere.', 'The question "Ni lipi limeandikwa vizuri?" with "JuMa ANakula" among the options.', 'Sort letter cards: capital only at the start; the rest small.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T2_HATI_NADHIFU_HERUFI_.HATI_NADHIFU.M1_HAT_SPACE_T2', 'KISW.G1.KUANDI.T2_HATI_NADHIFU_HERUFI_.HATI_NADHIFU', 'Leaves no space between words (Mamaanapika).', '{"question":"Ni lipi limeandikwa vizuri?","wrong_answer":"Mamaanapikachakula.","correct_answer":"Mama anapika chakula."}'::jsonb, 'Spoken Kiswahili runs words together; the child writes the stream as he hears it.', 'The question "Ni lipi limeandikwa vizuri?" with "Mamaanapikachakula." among the options.', 'Put a finger space after every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T2_HATI_NADHIFU_HERUFI_.HATI_NADHIFU.M1_HAT_TURN_T2', 'KISW.G1.KUANDI.T2_HATI_NADHIFU_HERUFI_.HATI_NADHIFU', 'Turns b and d (or p and q) round: dada written "baba" or "bada".', '{"question":"Andika neno \"dada\".","wrong_answer":"bada","correct_answer":"dada"}'::jsonb, 'Mirror letters are common in early writing; the child has not fixed the direction.', 'The question "Andika neno "dada"." with "bada" among the options.', 'Teach d as "c then a tall line"; trace it in sand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T2_HATI_NADHIFU_HERUFI_.HATI_NADHIFU.M1_HAT_LINE_T2', 'KISW.G1.KUANDI.T2_HATI_NADHIFU_HERUFI_.HATI_NADHIFU', 'Writes letters floating above the line or of mixed sizes, so the line goes up and down.', '{"question":"Maandishi nadhifu yanakaa wapi?","wrong_answer":"popote kwenye ukurasa","correct_answer":"juu ya mstari, herufi zikiwa na ukubwa sawa"}'::jsonb, 'The child writes fast and does not look at the line.', 'The question "Maandishi nadhifu yanakaa wapi?" with "popote kwenye ukurasa" among the options.', 'Trace the line with a finger first; every letter sits on it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T2_UMOJA_NA_WINGI_WA_MA.UMOJA_WINGI.M1_SAR_WRONGCLASS_T2', 'KISW.G1.SARUFI.T2_UMOJA_NA_WINGI_WA_MA.UMOJA_WINGI', 'Makes the plural with the prefix of another noun class (kitabu -> watabu).', '{"question":"Wingi wa \"kiti\" ni?","wrong_answer":"witi","correct_answer":"viti"}'::jsonb, 'The child knows that wa- makes people plural and uses it for everything; the ngeli of the noun is not yet known.', 'The question "Wingi wa "kiti" ni?" with "witi" among the options.', 'Sort noun cards into ngeli families (m-wa, ki-vi, li-ma, n-n) and say each plural aloud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T2_UMOJA_NA_WINGI_WA_MA.UMOJA_WINGI.M1_SAR_NUMWORD_T2', 'KISW.G1.SARUFI.T2_UMOJA_NA_WINGI_WA_MA.UMOJA_WINGI', 'Shows the plural only with a number word and leaves the noun singular (kitabu mbili).', '{"question":"Wingi wa \"mtoto mmoja\" ni?","wrong_answer":"mtoto wawili","correct_answer":"watoto wawili"}'::jsonb, 'English and some first languages keep the noun and add a number; Kiswahili changes the noun and the number agrees.', 'The question "Wingi wa "mtoto mmoja" ni?" with "mtoto wawili" among the options.', 'Line up two books: the child says vitabu viwili; then three: vitabu vitatu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T2_UMOJA_NA_WINGI_WA_MA.UMOJA_WINGI.M1_SAR_REVERSE_T2', 'KISW.G1.SARUFI.T2_UMOJA_NA_WINGI_WA_MA.UMOJA_WINGI', 'Takes the plural form for the singular (miti for one tree, vitabu for one book).', '{"question":"Ni lipi ni umoja?","wrong_answer":"vikombe","correct_answer":"kikombe"}'::jsonb, 'The child heard the plural more often (a tree is usually among trees) and learnt it as the name.', 'The question "Ni lipi ni umoja?" with "vikombe" among the options.', 'Hold one object, then many; the child names each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T2_UMOJA_NA_WINGI_WA_MA.UMOJA_WINGI.M1_SAR_NCLASS_T2', 'KISW.G1.SARUFI.T2_UMOJA_NA_WINGI_WA_MA.UMOJA_WINGI', 'Gives a noun of the n-n class a plural prefix (nyumba -> manyumba), or changes an irregular noun wrongly (jicho -> majicho).', '{"question":"Wingi wa \"kalamu\" ni?","wrong_answer":"makalamu","correct_answer":"kalamu"}'::jsonb, 'The child expects every plural to look different; n-n nouns stay the same and some li-ma nouns change their stem.', 'The question "Wingi wa "kalamu" ni?" with "makalamu" among the options.', 'Keep a short list of the same-in-both nouns (nyumba, ndizi, kalamu) and the irregular ones (jicho - macho, jino - meno).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T3_MANENO_YA_ADABU_NA_H.HESHIMA.M1_HES_POLE_T3', 'KISW.G1.KUSIKI.T3_MANENO_YA_ADABU_NA_H.HESHIMA', 'Says samahani when someone else is hurt by accident, where pole (sympathy) is meant.', '{"question":"Rafiki ameanguka mwenyewe uwanjani. Unamwambia nini?","wrong_answer":"Samahani","correct_answer":"Pole"}'::jsonb, 'English "sorry" covers both apology and sympathy; Kiswahili separates them: samahani when I did wrong, pole when you suffer.', 'The question "Rafiki ameanguka mwenyewe uwanjani. Unamwambia nini?" with "Samahani" among the options.', 'Two pictures: I stepped on your foot (samahani); you fell by yourself (pole). The child names each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T3_MANENO_YA_ADABU_NA_H.HESHIMA.M1_HES_KARIBU_T3', 'KISW.G1.KUSIKI.T3_MANENO_YA_ADABU_NA_H.HESHIMA', 'Answers "Asante" with "Asante" instead of "Karibu" (or "Si neno").', '{"question":"Ulimpa rafiki kalamu, akasema \"Asante.\" Unajibu nini?","wrong_answer":"Asante","correct_answer":"Karibu"}'::jsonb, 'The child echoes the polite word he has just heard.', 'The question "Ulimpa rafiki kalamu, akasema "Asante." Unajibu nini?" with "Asante" among the options.', 'Practise the pair with two children: one gives, one thanks, the giver answers Karibu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T3_MANENO_YA_ADABU_NA_H.HESHIMA.M1_HES_COMMAND_T3', 'KISW.G1.KUSIKI.T3_MANENO_YA_ADABU_NA_H.HESHIMA', 'Asks with a bare command (Nipe maji!) without tafadhali or naomba.', '{"question":"Unataka maji kutoka kwa mama. Unasemaje?","wrong_answer":"Nipe maji!","correct_answer":"Mama, tafadhali naomba maji."}'::jsonb, 'At home and in play the child hears short commands and copies them to adults.', 'The question "Unataka maji kutoka kwa mama. Unasemaje?" with "Nipe maji!" among the options.', 'Say both versions; the child says which one makes mama want to help.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T3_MANENO_YA_ADABU_NA_H.HESHIMA.M1_HES_TITLE_T3', 'KISW.G1.KUSIKI.T3_MANENO_YA_ADABU_NA_H.HESHIMA', 'Calls an adult by the bare first name without a title (Mwalimu, Mama, Baba, Bi., Bw.).', '{"question":"Unamwita mwalimu wako, Bi. Akinyi. Unasemaje?","wrong_answer":"Akinyi, njoo!","correct_answer":"Mwalimu, tafadhali njoo."}'::jsonb, 'Children call each other by name and carry the habit to adults.', 'The question "Unamwita mwalimu wako, Bi. Akinyi. Unasemaje?" with "Akinyi, njoo!" among the options.', 'Make title cards (Mwalimu, Mama, Babu, Daktari); the child puts one before each name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T3_MANENO_YA_ADABU_NA_H.HESHIMA.M1_HES_POLEREPLY_T3', 'KISW.G1.KUSIKI.T3_MANENO_YA_ADABU_NA_H.HESHIMA', 'Answers "Pole" with "Pole" instead of "Asante".', '{"question":"Rafiki anakuambia \"Pole kwa kuumia.\" Unajibu?","wrong_answer":"Pole","correct_answer":"Asante"}'::jsonb, 'The child echoes the word, as with greetings.', 'The question "Rafiki anakuambia "Pole kwa kuumia." Unajibu?" with "Pole" among the options.', 'Act it: one child is hurt, the other says pole, the hurt one says asante.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.UFAHAMU.M1_UFM_DECODE_T3', 'KISW.G1.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Reads every word aloud but cannot say what the passage was about.', '{"question":"Umesoma kifungu. Kinahusu nini?","wrong_answer":"Sijui, nilikuwa nikisoma maneno tu.","correct_answer":"Kifungu kinahusu kuku wa Juma."}'::jsonb, 'All the child''s effort goes into sounding out the words; nobody has asked him what the sentences said.', 'The question "Umesoma kifungu. Kinahusu nini?" with "Sijui, nilikuwa nikisoma maneno tu." among the options.', 'After each sentence stop and ask "Sentensi hii imesema nini?" before reading on.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.UFAHAMU.M1_UFM_WORD_T3', 'KISW.G1.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Gives "watano" the meaning of a word that looks or sounds like it.', '{"question":"Soma: \"Juma ana kuku watano. Kuku wawili ni weupe. Kuku watatu ni weusi. Juma anawapenda kuku wake.\" Neno \"watano\" lina maana gani?","wrong_answer":"watoto","correct_answer":"idadi ya tano"}'::jsonb, 'The child matches the word to a known one by its look instead of reading the sentence around it.', 'The question "Soma: "Juma ana kuku watano. Kuku wawili ni weupe. Kuku watatu ni weusi. Juma anawapenda kuku wake." Neno "watano" lina maana gani?" with "watoto" among the options.', 'Cover the word; the child says what word would fit the sentence, then uncovers it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.UFAHAMU.M1_UFM_MSG_T3', 'KISW.G1.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Gives one detail of the passage as its message.', '{"question":"Ujumbe wa kifungu ni upi?","wrong_answer":"Kuku wawili ni weupe.","correct_answer":"Juma ana kuku watano na anawapenda."}'::jsonb, 'The detail is what the child remembers best; he has not been asked what the writer wants us to know.', 'The question "Ujumbe wa kifungu ni upi?" with "Kuku wawili ni weupe." among the options.', 'Ask two questions side by side: "Nini kilitokea?" and "Kifungu kinatuambia nini?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.UFAHAMU.M1_UFM_OWN_T3', 'KISW.G1.KUSOMA.T3_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Answers from his own life instead of from the passage.', '{"question":"Juma ana kuku wangapi?","wrong_answer":"Sisi tuna kuku kumi.","correct_answer":"watano"}'::jsonb, 'The child links the question to what he knows from home and does not check the text.', 'The question "Juma ana kuku wangapi?" with "Sisi tuna kuku kumi." among the options.', 'Ask the child to point at the line in the passage that gives the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T3_HATI_NADHIFU_HERUFI_.HATI_NADHIFU.M1_HAT_TALL_T3', 'KISW.G1.KUANDI.T3_HATI_NADHIFU_HERUFI_.HATI_NADHIFU', 'Writes the tall small letters (b, d, h, k, l) short, so h looks like n.', '{"question":"Andika neno \"habari\". Ni lipi limeandikwa vizuri?","wrong_answer":"nabari","correct_answer":"habari"}'::jsonb, 'The child does not use the lines of the book: tall letters must reach the top line.', 'The question "Andika neno "habari". Ni lipi limeandikwa vizuri?" with "nabari" among the options.', 'Write on three-line paper; the child colours the part of h that goes up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T3_HATI_NADHIFU_HERUFI_.HATI_NADHIFU.M1_HAT_SIZE_T3', 'KISW.G1.KUANDI.T3_HATI_NADHIFU_HERUFI_.HATI_NADHIFU', 'Writes some small letters as big as capitals (kiti written kiTi or KITI).', '{"question":"Ni neno lipi limeandikwa kwa herufi ndogo vizuri?","wrong_answer":"KITI","correct_answer":"kiti"}'::jsonb, 'Capitals were learnt first in pre-primary and feel safer to write.', 'The question "Ni neno lipi limeandikwa kwa herufi ndogo vizuri?" with "KITI" among the options.', 'Compare k/K, s/S, t/T on cards; the child picks the small one for the middle of a word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T3_HATI_NADHIFU_HERUFI_.HATI_NADHIFU.M1_HAT_SPACE_T3', 'KISW.G1.KUANDI.T3_HATI_NADHIFU_HERUFI_.HATI_NADHIFU', 'Leaves no space between words (Mamaanapika).', '{"question":"Ni lipi limeandikwa vizuri?","wrong_answer":"Mamaanapikachakula.","correct_answer":"Mama anapika chakula."}'::jsonb, 'Spoken Kiswahili runs words together; the child writes the stream as he hears it.', 'The question "Ni lipi limeandikwa vizuri?" with "Mamaanapikachakula." among the options.', 'Put a finger space after every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T3_HATI_NADHIFU_HERUFI_.HATI_NADHIFU.M1_HAT_TURN_T3', 'KISW.G1.KUANDI.T3_HATI_NADHIFU_HERUFI_.HATI_NADHIFU', 'Turns b and d (or p and q) round: dada written "baba" or "bada".', '{"question":"Andika neno \"dada\".","wrong_answer":"bada","correct_answer":"dada"}'::jsonb, 'Mirror letters are common in early writing; the child has not fixed the direction.', 'The question "Andika neno "dada"." with "bada" among the options.', 'Teach d as "c then a tall line"; trace it in sand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T3_HATI_NADHIFU_HERUFI_.HATI_NADHIFU.M1_HAT_LINE_T3', 'KISW.G1.KUANDI.T3_HATI_NADHIFU_HERUFI_.HATI_NADHIFU', 'Writes letters floating above the line or of mixed sizes, so the line goes up and down.', '{"question":"Maandishi nadhifu yanakaa wapi?","wrong_answer":"popote kwenye ukurasa","correct_answer":"juu ya mstari, herufi zikiwa na ukubwa sawa"}'::jsonb, 'The child writes fast and does not look at the line.', 'The question "Maandishi nadhifu yanakaa wapi?" with "popote kwenye ukurasa" among the options.', 'Trace the line with a finger first; every letter sits on it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T3_MATUMIZI_YA_HUYU_NA_.VIONYESHI.M1_SAR_CLASSDEM_T3', 'KISW.G1.SARUFI.T3_MATUMIZI_YA_HUYU_NA_.VIONYESHI', 'Uses the people word (huyu, yule) for a thing (kiti huyu).', '{"question":"Jaza: Kiti ___ ni changu.","wrong_answer":"huyu","correct_answer":"hiki"}'::jsonb, 'Huyu was the first pointing word learnt; the child uses it for anything.', 'The question "Jaza: Kiti ___ ni changu." with "huyu" among the options.', 'Point at a child (huyu) and at a chair (hiki); then sort pictures by the pointing word they take.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T3_MATUMIZI_YA_HUYU_NA_.VIONYESHI.M1_SAR_NUMDEM_T3', 'KISW.G1.SARUFI.T3_MATUMIZI_YA_HUYU_NA_.VIONYESHI', 'Uses the one-thing pointing word with a plural noun (watoto huyu).', '{"question":"Jaza: Watoto ___ ni wanafunzi.","wrong_answer":"huyu","correct_answer":"hawa"}'::jsonb, 'The child changes the noun but not the pointing word.', 'The question "Jaza: Watoto ___ ni wanafunzi." with "huyu" among the options.', 'Pair the forms on cards: huyu-hawa, yule-wale, hiki-hivi, hili-haya.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T3_MATUMIZI_YA_HUYU_NA_.VIONYESHI.M1_SAR_HII_T3', 'KISW.G1.SARUFI.T3_MATUMIZI_YA_HUYU_NA_.VIONYESHI', 'Uses hii for every noun (kitabu hii, mtoto hii), as in town Kiswahili.', '{"question":"Jaza: Mtoto ___ ni dada yangu.","wrong_answer":"hii","correct_answer":"huyu"}'::jsonb, 'Hii is the pointing word heard most in town speech, where the noun class is dropped.', 'The question "Jaza: Mtoto ___ ni dada yangu." with "hii" among the options.', 'Read pairs aloud: kitabu hiki, mtoto huyu, nyumba hii; the child hears the match.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T3_MATUMIZI_YA_HUYU_NA_.VIONYESHI.M1_SAR_REVERSE_T3', 'KISW.G1.SARUFI.T3_MATUMIZI_YA_HUYU_NA_.VIONYESHI', 'Takes the plural form for the singular (miti for one tree, vitabu for one book).', '{"question":"Ni lipi ni la mtu mmoja?","wrong_answer":"hawa","correct_answer":"huyu"}'::jsonb, 'The child heard the plural more often (a tree is usually among trees) and learnt it as the name.', 'The question "Ni lipi ni la mtu mmoja?" with "hawa" among the options.', 'Hold one object, then many; the child names each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.MATAMSHI.M1_SAU_NEAR_T4', 'KISW.G1.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.MATAMSHI', 'Says /i/ for /e/, so "wewe" becomes "wiwi".', '{"question":"Mwalimu anasema \"wewe\". Neno lipi limetamkwa vizuri?","wrong_answer":"wiwi","correct_answer":"wewe"}'::jsonb, 'Many Kenyan first languages have no /e/, or do not separate it from /i/; the child puts in the home sound.', 'The question "Mwalimu anasema "wewe". Neno lipi limetamkwa vizuri?" with "wiwi" among the options.', 'Say the two side by side, slowly, watching the mouth; the child holds up a card for the sound he hears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.MATAMSHI.M1_SAU_NEAR2_T4', 'KISW.G1.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.MATAMSHI', 'Says /u/ for /o/, so "nono" becomes "nunu".', '{"question":"Neno lipi limetamkwa vizuri?","wrong_answer":"nunu","correct_answer":"nono"}'::jsonb, '/o/ and /u/ are close; a first language with only one of them puts that one in both places.', 'The question "Neno lipi limetamkwa vizuri?" with "nunu" among the options.', 'Contrast the two with a mirror and a hand before the mouth; the child says which he hears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.MATAMSHI.M1_SAU_SYLL_T4', 'KISW.G1.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.MATAMSHI', 'Splits "nane" by letters rather than by syllables (each Kiswahili syllable ends in a vowel).', '{"question":"Neno \"nane\" lina silabi zipi?","wrong_answer":"n-a-n-e","correct_answer":"na-ne"}'::jsonb, 'The child has learnt letters one by one and has not been shown that a syllable is a sound that ends in a vowel.', 'The question "Neno "nane" lina silabi zipi?" with "n-a-n-e" among the options.', 'Clap the word: one clap per vowel; the consonants go with the vowel after them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.MATAMSHI.M1_SAU_NAME_T4', 'KISW.G1.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.MATAMSHI', 'Says the English letter name instead of the Kiswahili sound (/e/ as "ii"), so the syllable cannot be built.', '{"question":"Sauti ya herufi \"e\" ni ipi?","wrong_answer":"ii","correct_answer":"/e/"}'::jsonb, 'English letter names are taught alongside and the child brings them to Kiswahili; a syllable is built from sounds, not names.', 'The question "Sauti ya herufi "e" ni ipi?" with "ii" among the options.', 'Say the sound alone, short (/e/), then join it to a vowel: ea, ee, ei.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.MATAMSHI.M1_SAU_PICK_T4', 'KISW.G1.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.MATAMSHI', 'Picks a word with no target sound when asked for one that has it.', '{"question":"Ni neno lipi lina sauti /n/, /o/, /w/, /e/, /i/, /h/?","wrong_answer":"mama","correct_answer":"wewe"}'::jsonb, 'The child looks at the first letter or the picture, not at the sound.', 'The question "Ni neno lipi lina sauti /n/, /o/, /w/, /e/, /i/, /h/?" with "mama" among the options.', 'Underline the target sound in each word on the card before choosing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M1_UFS_SOUND_T4', 'KISW.G1.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads the target word wrongly: "wewe" as "wiwi".', '{"question":"Neno \"wewe\" linasomwa vipi?","wrong_answer":"wiwi","correct_answer":"wewe"}'::jsonb, 'The child reads the letters with the sounds of his first language, or adds a vowel to break the cluster.', 'The question "Neno "wewe" linasomwa vipi?" with "wiwi" among the options.', 'Pick out the target words before reading; practise them on cards, then read the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M1_UFS_WORD_T4', 'KISW.G1.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Leo ni siku ya Jumanne.\"?","wrong_answer":"Leo ... ni ... siku ... ya ... Jumanne.","correct_answer":"Leo ni siku ya Jumanne."}'::jsonb, 'The child is still decoding each word; he has not yet read a group of words as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Leo ni siku ya Jumanne."?" with "Leo ... ni ... siku ... ya ... Jumanne." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it in one breath.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M1_UFS_QUIET_T4', 'KISW.G1.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads so softly (or so loudly, shouting) that the class cannot follow.', '{"question":"Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?","wrong_answer":"ya chini ili nisikosee mbele ya wenzangu","correct_answer":"ya kusikika na wote darasani, bila kupiga kelele"}'::jsonb, 'Shyness, or the belief that reading well means reading loud.', 'The question "Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?" with "ya chini ili nisikosee mbele ya wenzangu" among the options.', 'Stand the reader at the front and a listener at the back: the listener raises a hand when he hears every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M1_UFS_PACE_T4', 'KISW.G1.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Kasi ifaayo ya kusoma kifungu ni ipi?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, karibu maneno 15 kwa dakika"}'::jsonb, 'Reading races in class reward speed; nobody asked whether the listeners understood.', 'The question "Kasi ifaayo ya kusoma kifungu ni ipi?" with "haraka iwezekanavyo" among the options.', 'Time two readings, one very fast and one at speaking pace; the listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M1_UFS_MARK_T4', 'KISW.G1.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question in the flat voice of a statement and runs on through the koma and kikomo.', '{"question":"Sentensi \"Je, wewe uko nyumbani?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the marks.', 'The question "Sentensi "Je, wewe uko nyumbani?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that fits each reading; clap at each kikomo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T4_HATI_NADHIFU.KUUNGANISHA_SILABI.M1_UNG_GAPS_T4', 'KISW.G1.KUANDI.T4_HATI_NADHIFU.KUUNGANISHA_SILABI', 'Leaves a gap between every letter of a word (m a m a).', '{"question":"Ni lipi limeandikwa vizuri?","wrong_answer":"m a m a","correct_answer":"mama"}'::jsonb, 'The child learnt each letter alone and keeps a space after it.', 'The question "Ni lipi limeandikwa vizuri?" with "m a m a" among the options.', 'Write the syllable as one block (ma), then put two blocks together (mama), close.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T4_HATI_NADHIFU.KUUNGANISHA_SILABI.M1_UNG_ORDER_T4', 'KISW.G1.KUANDI.T4_HATI_NADHIFU.KUUNGANISHA_SILABI', 'Joins the syllables in the wrong order (ta + tu written tuta for tatu).', '{"question":"Unganisha silabi: ta + tu","wrong_answer":"tuta","correct_answer":"tatu"}'::jsonb, 'The child hears both syllables but writes the one he remembers best first.', 'The question "Unganisha silabi: ta + tu" with "tuta" among the options.', 'Clap the word and write one syllable per clap, in order, saying each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T4_HATI_NADHIFU.KUUNGANISHA_SILABI.M1_UNG_DROP_T4', 'KISW.G1.KUANDI.T4_HATI_NADHIFU.KUUNGANISHA_SILABI', 'Leaves out the vowel of a syllable (mm for mama, kk for kaka).', '{"question":"Unganisha silabi: ka + ka","wrong_answer":"kk","correct_answer":"kaka"}'::jsonb, 'The child writes the consonants he hears most strongly; the vowel ending each syllable is missed.', 'The question "Unganisha silabi: ka + ka" with "kk" among the options.', 'Every syllable ends in a vowel: say the vowel long (kaaa) and write it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T4_HATI_NADHIFU.KUUNGANISHA_SILABI.M1_UNG_LINES_T4', 'KISW.G1.KUANDI.T4_HATI_NADHIFU.KUUNGANISHA_SILABI', 'Writes each syllable on a new line, or one above the other.', '{"question":"Neno \"baba\" liandikwe vipi?","wrong_answer":"ba juu, ba chini","correct_answer":"baba katika mstari mmoja"}'::jsonb, 'Syllable cards were stacked in class and the child copies the stack.', 'The question "Neno "baba" liandikwe vipi?" with "ba juu, ba chini" among the options.', 'Lay the syllable cards side by side on the desk before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T4_UMOJA_NA_WINGI_WA_MA.UMOJA_WINGI.M1_SAR_WRONGCLASS_T4', 'KISW.G1.SARUFI.T4_UMOJA_NA_WINGI_WA_MA.UMOJA_WINGI', 'Makes the plural with the prefix of another noun class (kitabu -> watabu).', '{"question":"Wingi wa \"mti\" ni?","wrong_answer":"viti","correct_answer":"miti"}'::jsonb, 'The child knows that wa- makes people plural and uses it for everything; the ngeli of the noun is not yet known.', 'The question "Wingi wa "mti" ni?" with "viti" among the options.', 'Sort noun cards into ngeli families (m-wa, ki-vi, li-ma, n-n) and say each plural aloud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T4_UMOJA_NA_WINGI_WA_MA.UMOJA_WINGI.M1_SAR_NCLASS_T4', 'KISW.G1.SARUFI.T4_UMOJA_NA_WINGI_WA_MA.UMOJA_WINGI', 'Gives a noun of the n-n class a plural prefix (nyumba -> manyumba), or changes an irregular noun wrongly (jicho -> majicho).', '{"question":"Wingi wa \"jicho\" ni?","wrong_answer":"majicho","correct_answer":"macho"}'::jsonb, 'The child expects every plural to look different; n-n nouns stay the same and some li-ma nouns change their stem.', 'The question "Wingi wa "jicho" ni?" with "majicho" among the options.', 'Keep a short list of the same-in-both nouns (nyumba, ndizi, kalamu) and the irregular ones (jicho - macho, jino - meno).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T4_UMOJA_NA_WINGI_WA_MA.UMOJA_WINGI.M1_SAR_NUMWORD_T4', 'KISW.G1.SARUFI.T4_UMOJA_NA_WINGI_WA_MA.UMOJA_WINGI', 'Shows the plural only with a number word and leaves the noun singular (kitabu mbili).', '{"question":"Wingi wa \"yai moja\" ni?","wrong_answer":"yai mbili","correct_answer":"mayai mawili"}'::jsonb, 'English and some first languages keep the noun and add a number; Kiswahili changes the noun and the number agrees.', 'The question "Wingi wa "yai moja" ni?" with "yai mbili" among the options.', 'Line up two books: the child says vitabu viwili; then three: vitabu vitatu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T4_UMOJA_NA_WINGI_WA_MA.UMOJA_WINGI.M1_SAR_REVERSE_T4', 'KISW.G1.SARUFI.T4_UMOJA_NA_WINGI_WA_MA.UMOJA_WINGI', 'Takes the plural form for the singular (miti for one tree, vitabu for one book).', '{"question":"Ni lipi ni umoja?","wrong_answer":"majani","correct_answer":"jani"}'::jsonb, 'The child heard the plural more often (a tree is usually among trees) and learnt it as the name.', 'The question "Ni lipi ni umoja?" with "majani" among the options.', 'Hold one object, then many; the child names each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA.M1_SIK_DETAIL_T5', 'KISW.G1.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA', 'Gives a detail of the passage as its message.', '{"question":"Ujumbe wa kifungu ulichosikiliza ni upi?","wrong_answer":"Kamau alisahau chakula.","correct_answer":"Tushiriki tulicho nacho na wenzetu."}'::jsonb, 'The detail is the clearest thing the child remembers; he has not been asked what the passage teaches.', 'The question "Ujumbe wa kifungu ulichosikiliza ni upi?" with "Kamau alisahau chakula." among the options.', 'After listening, ask "Kifungu kinatufundisha nini?" and compare it with "Nini kilitokea?".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA.M1_SIK_WORD_T5', 'KISW.G1.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA', 'Gives "kushiriki" the meaning of a word that sounds like it.', '{"question":"Neno \"kushiriki\" katika kifungu lina maana gani?","wrong_answer":"kushinda","correct_answer":"kugawana kitu na mwenzako"}'::jsonb, 'The child matches the sound of the word to one he knows instead of listening to the sentence around it.', 'The question "Neno "kushiriki" katika kifungu lina maana gani?" with "kushinda" among the options.', 'Replay the sentence; the child tries each meaning in it and keeps the one that makes sense.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA.M1_SIK_SENT_T5', 'KISW.G1.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA', 'Makes a "sentence" that only repeats the word and shows no meaning (kushiriki ni kushiriki).', '{"question":"Ni sentensi ipi inaonyesha maana ya \"kushiriki\"?","wrong_answer":"Kushiriki ni kushiriki.","correct_answer":"Tulishiriki mkate darasani."}'::jsonb, 'The child thinks any sentence with the word in it is enough.', 'The question "Ni sentensi ipi inaonyesha maana ya "kushiriki"?" with "Kushiriki ni kushiriki." among the options.', 'Ask: if your friend did not know the word, would your sentence tell him what it means?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA.M1_SIK_ORDER_T5', 'KISW.G1.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA', 'Retells the events out of order.', '{"question":"Panga matukio ya kifungu kama yalivyotokea.","wrong_answer":"Walikula pamoja, Kamau alisahau chakula, Otieno alimgawia","correct_answer":"Kamau alisahau chakula, Otieno alimgawia, walikula pamoja"}'::jsonb, 'The child remembers the most exciting event and tells it first.', 'The question "Panga matukio ya kifungu kama yalivyotokea." with "Walikula pamoja, Kamau alisahau chakula, Otieno alimgawia" among the options.', 'Three picture cards of the events; the child lays them left to right and retells with kwanza, kisha, mwishowe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA.M1_SIK_ADD_T5', 'KISW.G1.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA', 'Adds events that were not in the passage when retelling.', '{"question":"Unaposimulia upya, unaongeza mambo ambayo hayakuwa kwenye kifungu?","wrong_answer":"ndiyo, ili hadithi iwe tamu","correct_answer":"hapana, ninasimulia yaliyokuwemo tu"}'::jsonb, 'Retelling is taken as storytelling: the child invents to make it longer.', 'The question "Unaposimulia upya, unaongeza mambo ambayo hayakuwa kwenye kifungu?" with "ndiyo, ili hadithi iwe tamu" among the options.', 'After the retelling, the class checks each event: was it in the passage? Thumbs up or down.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T5_KUSOMA_KWA_UFAHAMU_K.UFAHAMU.M1_UFM_DECODE_T5', 'KISW.G1.KUSOMA.T5_KUSOMA_KWA_UFAHAMU_K.UFAHAMU', 'Reads every word aloud but cannot say what the passage was about.', '{"question":"Umesoma kifungu. Kinahusu nini?","wrong_answer":"Sijui, nilikuwa nikisoma maneno tu.","correct_answer":"Kifungu kinahusu Akinyi na rafiki yake Wanjiku."}'::jsonb, 'All the child''s effort goes into sounding out the words; nobody has asked him what the sentences said.', 'The question "Umesoma kifungu. Kinahusu nini?" with "Sijui, nilikuwa nikisoma maneno tu." among the options.', 'After each sentence stop and ask "Sentensi hii imesema nini?" before reading on.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T5_KUSOMA_KWA_UFAHAMU_K.UFAHAMU.M1_UFM_WORD_T5', 'KISW.G1.KUSOMA.T5_KUSOMA_KWA_UFAHAMU_K.UFAHAMU', 'Gives "tunasaidiana" the meaning of a word that looks or sounds like it.', '{"question":"Soma: \"Mimi ni Akinyi. Nina rafiki anayeitwa Wanjiku. Tunacheza pamoja shuleni. Tunasaidiana kila siku.\" Neno \"tunasaidiana\" lina maana gani?","wrong_answer":"tunasalimiana","correct_answer":"kila mmoja anamsaidia mwenzake"}'::jsonb, 'The child matches the word to a known one by its look instead of reading the sentence around it.', 'The question "Soma: "Mimi ni Akinyi. Nina rafiki anayeitwa Wanjiku. Tunacheza pamoja shuleni. Tunasaidiana kila siku." Neno "tunasaidiana" lina maana gani?" with "tunasalimiana" among the options.', 'Cover the word; the child says what word would fit the sentence, then uncovers it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T5_KUSOMA_KWA_UFAHAMU_K.UFAHAMU.M1_UFM_MSG_T5', 'KISW.G1.KUSOMA.T5_KUSOMA_KWA_UFAHAMU_K.UFAHAMU', 'Gives one detail of the passage as its message.', '{"question":"Ujumbe wa kifungu ni upi?","wrong_answer":"Akinyi yuko shuleni.","correct_answer":"Marafiki hucheza pamoja na kusaidiana."}'::jsonb, 'The detail is what the child remembers best; he has not been asked what the writer wants us to know.', 'The question "Ujumbe wa kifungu ni upi?" with "Akinyi yuko shuleni." among the options.', 'Ask two questions side by side: "Nini kilitokea?" and "Kifungu kinatuambia nini?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T5_KUSOMA_KWA_UFAHAMU_K.UFAHAMU.M1_UFM_OWN_T5', 'KISW.G1.KUSOMA.T5_KUSOMA_KWA_UFAHAMU_K.UFAHAMU', 'Answers from his own life instead of from the passage.', '{"question":"Rafiki wa Akinyi anaitwa nani?","wrong_answer":"Rafiki yangu ni Otieno.","correct_answer":"Wanjiku"}'::jsonb, 'The child links the question to what he knows from home and does not check the text.', 'The question "Rafiki wa Akinyi anaitwa nani?" with "Rafiki yangu ni Otieno." among the options.', 'Ask the child to point at the line in the passage that gives the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T5_MATUMIZI_YA_KIKOMO.ALAMA.M1_ALA_NOSTOP_T5', 'KISW.G1.KUANDI.T5_MATUMIZI_YA_KIKOMO.ALAMA', 'Runs sentences together with no kikomo.', '{"question":"Ni lipi limeandikwa vizuri?","wrong_answer":"Juma alienda shuleni alisoma vizuri alirudi nyumbani","correct_answer":"Juma alienda shuleni. Alisoma vizuri. Alirudi nyumbani."}'::jsonb, 'The child writes as he speaks, one long breath.', 'The question "Ni lipi limeandikwa vizuri?" with "Juma alienda shuleni alisoma vizuri alirudi nyumbani" among the options.', 'Read the writing aloud; where the breath stops, put a kikomo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T5_MATUMIZI_YA_KIKOMO.ALAMA.M1_ALA_LINE_T5', 'KISW.G1.KUANDI.T5_MATUMIZI_YA_KIKOMO.ALAMA', 'Puts a kikomo at the end of every line of writing, not at the end of the sentence.', '{"question":"Kikomo huwekwa wapi?","wrong_answer":"mwishoni mwa kila mstari wa daftari","correct_answer":"mwishoni mwa sentensi"}'::jsonb, 'The line of the book looks like the end of a sentence.', 'The question "Kikomo huwekwa wapi?" with "mwishoni mwa kila mstari wa daftari" among the options.', 'Write one sentence that runs over two lines; the child finds where it really ends.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T5_MATUMIZI_YA_KIKOMO.ALAMA.M1_ALA_CAP_T5', 'KISW.G1.KUANDI.T5_MATUMIZI_YA_KIKOMO.ALAMA', 'Writes a small letter after a kikomo or kiulizi.', '{"question":"Ni lipi sahihi?","wrong_answer":"Mimi ni Amina. mama alifurahi.","correct_answer":"Mimi ni Amina. Mama alifurahi."}'::jsonb, 'The child does not link the mark to the capital that follows it.', 'The question "Ni lipi sahihi?" with "Mimi ni Amina. mama alifurahi." among the options.', 'Every kikomo is a gate: the next word starts big.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T5_MATUMIZI_YA_KIKOMO.ALAMA.M1_ALA_STOPQ_T5', 'KISW.G1.KUANDI.T5_MATUMIZI_YA_KIKOMO.ALAMA', 'Ends a question with a kikomo.', '{"question":"Weka alama sahihi: Unaenda wapi","wrong_answer":"Unaenda wapi.","correct_answer":"Unaenda wapi?"}'::jsonb, 'The child ends every sentence the same way.', 'The question "Weka alama sahihi: Unaenda wapi" with "Unaenda wapi." among the options.', 'Read the sentence aloud: if the voice rises and asks, it takes a kiulizi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T5_MATUMIZI_YA_ANGU_NA_.VIMILIKISHI.M1_SAR_CONCPOSS_T5', 'KISW.G1.SARUFI.T5_MATUMIZI_YA_ANGU_NA_.VIMILIKISHI', 'Uses the wrong noun-class form of the possessive (kitabu yangu for kitabu changu).', '{"question":"Jaza: Kitabu ___ (-angu) ni kipya.","wrong_answer":"yangu","correct_answer":"changu"}'::jsonb, 'Town Kiswahili uses yangu, yako, yake for every noun; the child has not seen the ngeli agreement.', 'The question "Jaza: Kitabu ___ (-angu) ni kipya." with "yangu" among the options.', 'Pair nouns and possessives by colour: kitabu changu, kiti chake, mtoto wangu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T5_MATUMIZI_YA_ANGU_NA_.VIMILIKISHI.M1_SAR_NUMPOSS_T5', 'KISW.G1.SARUFI.T5_MATUMIZI_YA_ANGU_NA_.VIMILIKISHI', 'Leaves the possessive singular with a plural noun (vitabu changu).', '{"question":"Jaza: Vitabu ___ (-angu) ni vipya.","wrong_answer":"changu","correct_answer":"vyangu"}'::jsonb, 'The child changes the noun and forgets the possessive.', 'The question "Jaza: Vitabu ___ (-angu) ni vipya." with "changu" among the options.', 'Change one object to many in front of the child; both words change.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T5_MATUMIZI_YA_ANGU_NA_.VIMILIKISHI.M1_SAR_OWNER_T5', 'KISW.G1.SARUFI.T5_MATUMIZI_YA_ANGU_NA_.VIMILIKISHI', 'Uses the possessive of the wrong owner (-ake for something that is his own, -ake for many owners).', '{"question":"Mimi na wenzangu tuna darasa. Ni darasa ___.","wrong_answer":"langu","correct_answer":"letu"}'::jsonb, 'The child has not linked -angu, -ako, -ake, -etu, -enu, -ao to who owns the thing.', 'The question "Mimi na wenzangu tuna darasa. Ni darasa ___." with "langu" among the options.', 'Hold up an object: Ni cha nani? Answer with the owner first, then the possessive.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T5_MATUMIZI_YA_ANGU_NA_.VIMILIKISHI.M1_SAR_ORDERPOSS_T5', 'KISW.G1.SARUFI.T5_MATUMIZI_YA_ANGU_NA_.VIMILIKISHI', 'Puts the possessive before the noun (yangu kalamu), in English word order.', '{"question":"Ni lipi sahihi?","wrong_answer":"yangu kalamu","correct_answer":"kalamu yangu"}'::jsonb, 'English puts "my" before the noun; Kiswahili puts it after.', 'The question "Ni lipi sahihi?" with "yangu kalamu" among the options.', 'Build the phrase with cards: the noun first, then the possessive.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI.M1_SAU_NEAR_T6', 'KISW.G1.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI', 'Says /t/ for /d/, so "damu" becomes "tamu".', '{"question":"Mwalimu anasema \"damu\". Neno lipi limetamkwa vizuri?","wrong_answer":"tamu","correct_answer":"damu"}'::jsonb, 'Many Kenyan first languages have no /d/, or do not separate it from /t/; the child puts in the home sound.', 'The question "Mwalimu anasema "damu". Neno lipi limetamkwa vizuri?" with "tamu" among the options.', 'Say the two side by side, slowly, watching the mouth; the child holds up a card for the sound he hears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI.M1_SAU_NEAR2_T6', 'KISW.G1.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI', 'Says /s/ for /z/, so "ziwa" becomes "siwa".', '{"question":"Neno lipi limetamkwa vizuri?","wrong_answer":"siwa","correct_answer":"ziwa"}'::jsonb, '/z/ and /s/ are close; a first language with only one of them puts that one in both places.', 'The question "Neno lipi limetamkwa vizuri?" with "siwa" among the options.', 'Contrast the two with a mirror and a hand before the mouth; the child says which he hears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI.M1_SAU_SYLL_T6', 'KISW.G1.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI', 'Splits "sikio" by letters rather than by syllables (each Kiswahili syllable ends in a vowel).', '{"question":"Neno \"sikio\" lina silabi zipi?","wrong_answer":"s-i-k-i-o","correct_answer":"si-ki-o"}'::jsonb, 'The child has learnt letters one by one and has not been shown that a syllable is a sound that ends in a vowel.', 'The question "Neno "sikio" lina silabi zipi?" with "s-i-k-i-o" among the options.', 'Clap the word: one clap per vowel; the consonants go with the vowel after them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI.M1_SAU_NAME_T6', 'KISW.G1.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI', 'Says the English letter name instead of the Kiswahili sound (/g/ as "ji"), so the syllable cannot be built.', '{"question":"Sauti ya herufi \"g\" ni ipi?","wrong_answer":"ji","correct_answer":"/g/"}'::jsonb, 'English letter names are taught alongside and the child brings them to Kiswahili; a syllable is built from sounds, not names.', 'The question "Sauti ya herufi "g" ni ipi?" with "ji" among the options.', 'Say the sound alone, short (/g/), then join it to a vowel: ga, ge, gi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI.M1_SAU_PICK_T6', 'KISW.G1.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI', 'Picks a word with no target sound when asked for one that has it.', '{"question":"Ni neno lipi lina sauti /s/, /b/, /y/, /z/, /g/, /d/?","wrong_answer":"mkono","correct_answer":"bega"}'::jsonb, 'The child looks at the first letter or the picture, not at the sound.', 'The question "Ni neno lipi lina sauti /s/, /b/, /y/, /z/, /g/, /d/?" with "mkono" among the options.', 'Underline the target sound in each word on the card before choosing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T6_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI.M1_UFS_SOUND_T6', 'KISW.G1.KUSOMA.T6_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI', 'Reads the target word wrongly: "damu" as "tamu".', '{"question":"Neno \"damu\" linasomwa vipi?","wrong_answer":"tamu","correct_answer":"damu"}'::jsonb, 'The child reads the letters with the sounds of his first language, or adds a vowel to break the cluster.', 'The question "Neno "damu" linasomwa vipi?" with "tamu" among the options.', 'Pick out the target words before reading; practise them on cards, then read the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T6_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI.M1_UFS_WORD_T6', 'KISW.G1.KUSOMA.T6_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Baba ana sikio na bega.\"?","wrong_answer":"Baba ... ana ... sikio ... na ... bega.","correct_answer":"Baba ana sikio na bega."}'::jsonb, 'The child is still decoding each word; he has not yet read a group of words as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Baba ana sikio na bega."?" with "Baba ... ana ... sikio ... na ... bega." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it in one breath.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T6_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI.M1_UFS_QUIET_T6', 'KISW.G1.KUSOMA.T6_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI', 'Reads so softly (or so loudly, shouting) that the class cannot follow.', '{"question":"Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?","wrong_answer":"ya chini ili nisikosee mbele ya wenzangu","correct_answer":"ya kusikika na wote darasani, bila kupiga kelele"}'::jsonb, 'Shyness, or the belief that reading well means reading loud.', 'The question "Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?" with "ya chini ili nisikosee mbele ya wenzangu" among the options.', 'Stand the reader at the front and a listener at the back: the listener raises a hand when he hears every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T6_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI.M1_UFS_PACE_T6', 'KISW.G1.KUSOMA.T6_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Kasi ifaayo ya kusoma kifungu ni ipi?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, karibu maneno 20 kwa dakika"}'::jsonb, 'Reading races in class reward speed; nobody asked whether the listeners understood.', 'The question "Kasi ifaayo ya kusoma kifungu ni ipi?" with "haraka iwezekanavyo" among the options.', 'Time two readings, one very fast and one at speaking pace; the listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T6_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI.M1_UFS_MARK_T6', 'KISW.G1.KUSOMA.T6_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI', 'Reads a question in the flat voice of a statement and runs on through the koma and kikomo.', '{"question":"Sentensi \"Je, goti lako linauma?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the marks.', 'The question "Sentensi "Je, goti lako linauma?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that fits each reading; clap at each kikomo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T6_TAHAJIA_IMLA.IMLA.M1_TAH_MT_T6', 'KISW.G1.KUANDI.T6_TAHAJIA_IMLA.IMLA', 'Spells the word with the sound of his first language: "damu" written "tamu".', '{"question":"Ni tahajia ipi sahihi?","wrong_answer":"tamu","correct_answer":"damu"}'::jsonb, 'The child writes as he says the word; if his first language merges the two sounds, the letter is a guess.', 'The question "Ni tahajia ipi sahihi?" with "tamu" among the options.', 'Keep a list of the class''s hard pairs (l/r, s/sh, z/dh, s/th); say each word slowly before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T6_TAHAJIA_IMLA.IMLA.M1_TAH_NASAL_T6', 'KISW.G1.KUANDI.T6_TAHAJIA_IMLA.IMLA', 'Drops the nasal: "ndevu" written "devu".', '{"question":"Ni tahajia ipi sahihi?","wrong_answer":"devu","correct_answer":"ndevu"}'::jsonb, 'The n or m before a consonant is soft and quick; the child does not hear it.', 'The question "Ni tahajia ipi sahihi?" with "devu" among the options.', 'Hum the nasal before the word (mmm-bwa, nnn-dege).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T6_TAHAJIA_IMLA.IMLA.M1_TAH_VOWEL_T6', 'KISW.G1.KUANDI.T6_TAHAJIA_IMLA.IMLA', 'Writes a long vowel short, so the word changes: "kaa" written "ka".', '{"question":"Andika neno lenye maana ya \"kuketi\".","wrong_answer":"ka","correct_answer":"kaa"}'::jsonb, 'The child hears the length but does not know it is shown by two letters.', 'The question "Andika neno lenye maana ya "kuketi"." with "ka" among the options.', 'Clap the two vowels as two beats; compare a word with one and two vowels.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T6_TAHAJIA_IMLA.IMLA.M1_TAH_NGAPOS_T6', 'KISW.G1.KUANDI.T6_TAHAJIA_IMLA.IMLA', 'Writes ng'' without the apostrophe (ngombe for ng''ombe), or puts it where it does not belong (ng''oma for ngoma).', '{"question":"Ni tahajia ipi sahihi ya mnyama anayetupa maziwa?","wrong_answer":"ngombe","correct_answer":"ng''ombe"}'::jsonb, 'Ng'' and ng are two sounds; the apostrophe looks like dirt on the page to the child.', 'The question "Ni tahajia ipi sahihi ya mnyama anayetupa maziwa?" with "ngombe" among the options.', 'Say ng''ombe and ngoma: the first has no g sound; mark it with the apostrophe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T6_TAHAJIA_IMLA.IMLA.M1_TAH_JOIN_T6', 'KISW.G1.KUANDI.T6_TAHAJIA_IMLA.IMLA', 'Joins two words into one, or splits one word into two (kwasababu; mwana funzi).', '{"question":"Ni lipi sahihi?","wrong_answer":"Nilichelewa kwasababu ya mvua.","correct_answer":"Nilichelewa kwa sababu ya mvua."}'::jsonb, 'In speech the words run together; the child has not seen each written apart.', 'The question "Ni lipi sahihi?" with "Nilichelewa kwasababu ya mvua." among the options.', 'Count the words aloud with a finger for each before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T6_MATUMIZI_YA_ZURI_NA_.VIVUMISHI.M1_SAR_CONCADJ_T6', 'KISW.G1.SARUFI.T6_MATUMIZI_YA_ZURI_NA_.VIVUMISHI', 'Gives the adjective the people prefix whatever the noun (kiti mzuri).', '{"question":"Jaza: Kitabu ___ (-zuri).","wrong_answer":"mzuri","correct_answer":"kizuri"}'::jsonb, 'Mzuri is the form the child hears most (mtoto mzuri) and is used everywhere.', 'The question "Jaza: Kitabu ___ (-zuri)." with "mzuri" among the options.', 'Match noun and adjective by colour: kiti kizuri, mtoto mzuri, vitu vizuri.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T6_MATUMIZI_YA_ZURI_NA_.VIVUMISHI.M1_SAR_NADJ_T6', 'KISW.G1.SARUFI.T6_MATUMIZI_YA_ZURI_NA_.VIVUMISHI', 'Gives an n-n noun the m- form of the adjective (nyumba mzuri for nyumba nzuri).', '{"question":"Jaza: Nguo ___ (-zuri).","wrong_answer":"mzuri","correct_answer":"nzuri"}'::jsonb, 'The n- prefix and its sound changes (nzuri, ndefu, nyeupe) are new to the child.', 'The question "Jaza: Nguo ___ (-zuri)." with "mzuri" among the options.', 'Read pairs aloud: nyumba nzuri, kalamu ndefu, nguo nyeupe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T6_MATUMIZI_YA_ZURI_NA_.VIVUMISHI.M1_SAR_ORDERADJ_T6', 'KISW.G1.SARUFI.T6_MATUMIZI_YA_ZURI_NA_.VIVUMISHI', 'Puts the adjective before the noun (mzuri mtoto), in English word order.', '{"question":"Ni lipi sahihi?","wrong_answer":"mzuri mtoto","correct_answer":"mtoto mzuri"}'::jsonb, 'English puts the describing word first.', 'The question "Ni lipi sahihi?" with "mzuri mtoto" among the options.', 'Build with cards: noun first, then the adjective.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T6_MATUMIZI_YA_ZURI_NA_.VIVUMISHI.M1_SAR_PLADJ_T6', 'KISW.G1.SARUFI.T6_MATUMIZI_YA_ZURI_NA_.VIVUMISHI', 'Leaves the adjective singular with a plural noun (watoto mzuri).', '{"question":"Jaza: Watoto ___ (-zuri).","wrong_answer":"mzuri","correct_answer":"wazuri"}'::jsonb, 'The child changes the noun only.', 'The question "Jaza: Watoto ___ (-zuri)." with "mzuri" among the options.', 'Change the noun to many and ask the child to change every word that goes with it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T6_MATUMIZI_YA_ZURI_NA_.VIVUMISHI.M1_SAR_OPPADJ_T6', 'KISW.G1.SARUFI.T6_MATUMIZI_YA_ZURI_NA_.VIVUMISHI', 'Picks the opposite member of the pair (mrefu for a short person).', '{"question":"Picha inaonyesha meno machafu yenye mashimo. Meno ni ___.","wrong_answer":"mazuri","correct_answer":"mabaya"}'::jsonb, 'The pair is learnt together and the two words are swapped.', 'The question "Picha inaonyesha meno machafu yenye mashimo. Meno ni ___." with "mazuri" among the options.', 'Act the pairs with the body: stretch for refu, crouch for fupi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T7_MAAGIZO.MAAGIZO.M1_MAG_HALF_T7', 'KISW.G1.KUSIKI.T7_MAAGIZO.MAAGIZO', 'Carries out only the first part of a two-step instruction.', '{"question":"Agizo: \"Osha mikono, kisha uikaushe.\" Umefanya nini?","wrong_answer":"anaosha mikono tu","correct_answer":"anaosha mikono kisha anaikausha"}'::jsonb, 'The child starts acting as soon as he hears the first verb and stops listening.', 'The question "Agizo: "Osha mikono, kisha uikaushe." Umefanya nini?" with "anaosha mikono tu" among the options.', 'Hold up one finger for each step while giving the instruction; the child repeats the steps before moving.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T7_MAAGIZO.MAAGIZO.M1_MAG_ORDER_T7', 'KISW.G1.KUSIKI.T7_MAAGIZO.MAAGIZO', 'Does the steps in the wrong order.', '{"question":"Agizo: \"Osha mikono, kisha ule chakula.\" Ni nini kinatangulia?","wrong_answer":"kula chakula","correct_answer":"kuosha mikono"}'::jsonb, 'The child does the step he wants most first; the order words kwanza and kisha are not yet noticed.', 'The question "Agizo: "Osha mikono, kisha ule chakula." Ni nini kinatangulia?" with "kula chakula" among the options.', 'Number the steps on the board with kwanza, kisha, mwishowe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T7_MAAGIZO.MAAGIZO.M1_MAG_DIR_T7', 'KISW.G1.KUSIKI.T7_MAAGIZO.MAAGIZO', 'Mixes a direction or action word.', '{"question":"Agizo: \"Inua mkono wa kulia.\" Ni kitendo kipi sahihi?","wrong_answer":"anainua mkono wa kushoto","correct_answer":"anainua mkono wa kulia"}'::jsonb, 'Pairs such as kulia/kushoto and juu/chini are learnt together and swapped.', 'The question "Agizo: "Inua mkono wa kulia." Ni kitendo kipi sahihi?" with "anainua mkono wa kushoto" among the options.', 'Play "Mwalimu anasema": the teacher calls the word, the child acts it; mark the right hand with a band.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T7_MAAGIZO.MAAGIZO.M1_MAG_VAGUE_T7', 'KISW.G1.KUSIKI.T7_MAAGIZO.MAAGIZO', 'Gives an instruction that leaves out what to act on, or with no polite word (Lete!).', '{"question":"Ni agizo lipi liko wazi na lina adabu?","wrong_answer":"Lete!","correct_answer":"Tafadhali lete kitabu chako mezani."}'::jsonb, 'The child knows what he means and does not see that the listener cannot.', 'The question "Ni agizo lipi liko wazi na lina adabu?" with "Lete!" among the options.', 'The child gives the instruction to a partner, who does exactly what was said and no more.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.UFAHAMU.M1_UFM_WORD_T7', 'KISW.G1.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Gives "husugua" the meaning of a word that looks or sounds like it.', '{"question":"Soma: \"Kila asubuhi Baraka huoga kwa maji na sabuni. Yeye husugua meno na kuchana nywele. Baraka huwa safi.\" Neno \"husugua\" lina maana gani?","wrong_answer":"husahau","correct_answer":"husafisha kwa kusugua"}'::jsonb, 'The child matches the word to a known one by its look instead of reading the sentence around it.', 'The question "Soma: "Kila asubuhi Baraka huoga kwa maji na sabuni. Yeye husugua meno na kuchana nywele. Baraka huwa safi." Neno "husugua" lina maana gani?" with "husahau" among the options.', 'Cover the word; the child says what word would fit the sentence, then uncovers it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.UFAHAMU.M1_UFM_MSG_T7', 'KISW.G1.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Gives one detail of the passage as its message.', '{"question":"Ujumbe wa kifungu ni upi?","wrong_answer":"Baraka huchana nywele.","correct_answer":"Tuoge na kusafisha mwili kila siku."}'::jsonb, 'The detail is what the child remembers best; he has not been asked what the writer wants us to know.', 'The question "Ujumbe wa kifungu ni upi?" with "Baraka huchana nywele." among the options.', 'Ask two questions side by side: "Nini kilitokea?" and "Kifungu kinatuambia nini?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.UFAHAMU.M1_UFM_GUESS_T7', 'KISW.G1.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Predicts something the passage gives no clue for, without looking at the picture.', '{"question":"Picha inaonyesha mikono michafu ya Baraka kabla ya chakula. Atafanya nini?","wrong_answer":"Atakula moja kwa moja.","correct_answer":"Ataosha mikono kwa sabuni."}'::jsonb, 'Prediction is taken as free imagination; the child has not been shown that clues in the text and picture point the way.', 'The question "Picha inaonyesha mikono michafu ya Baraka kabla ya chakula. Atafanya nini?" with "Atakula moja kwa moja." among the options.', 'Underline the clue words and point at the picture; the guess must fit them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.UFAHAMU.M1_UFM_LESSON_T7', 'KISW.G1.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Retells what happened when asked for the lesson.', '{"question":"Tunajifunza nini kutokana na kifungu?","wrong_answer":"Baraka huoga asubuhi.","correct_answer":"Tunapaswa kuweka miili yetu safi."}'::jsonb, 'The lesson question sounds like a what-happened question to the child.', 'The question "Tunajifunza nini kutokana na kifungu?" with "Baraka huoga asubuhi." among the options.', 'Start the answer with "Tunajifunza kwamba tunapaswa..."', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.UFAHAMU.M1_UFM_OWN_T7', 'KISW.G1.KUSOMA.T7_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Answers from his own life instead of from the passage.', '{"question":"Baraka huoga kwa nini?","wrong_answer":"Mimi huoga kwa maji moto.","correct_answer":"maji na sabuni"}'::jsonb, 'The child links the question to what he knows from home and does not check the text.', 'The question "Baraka huoga kwa nini?" with "Mimi huoga kwa maji moto." among the options.', 'Ask the child to point at the line in the passage that gives the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T7_KUANDIKA_MANENO_IPAS.TAHAJIA.M1_TAH_MT_T7', 'KISW.G1.KUANDI.T7_KUANDIKA_MANENO_IPAS.TAHAJIA', 'Spells the word with the sound of his first language: "taulo" written "tauro".', '{"question":"Ni tahajia ipi sahihi?","wrong_answer":"tauro","correct_answer":"taulo"}'::jsonb, 'The child writes as he says the word; if his first language merges the two sounds, the letter is a guess.', 'The question "Ni tahajia ipi sahihi?" with "tauro" among the options.', 'Keep a list of the class''s hard pairs (l/r, s/sh, z/dh, s/th); say each word slowly before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T7_KUANDIKA_MANENO_IPAS.TAHAJIA.M1_TAH_NASAL_T7', 'KISW.G1.KUANDI.T7_KUANDIKA_MANENO_IPAS.TAHAJIA', 'Drops the nasal: "ndoo" written "doo".', '{"question":"Ni tahajia ipi sahihi?","wrong_answer":"doo","correct_answer":"ndoo"}'::jsonb, 'The n or m before a consonant is soft and quick; the child does not hear it.', 'The question "Ni tahajia ipi sahihi?" with "doo" among the options.', 'Hum the nasal before the word (mmm-bwa, nnn-dege).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T7_KUANDIKA_MANENO_IPAS.TAHAJIA.M1_TAH_VOWEL_T7', 'KISW.G1.KUANDI.T7_KUANDIKA_MANENO_IPAS.TAHAJIA', 'Writes a long vowel short, so the word changes: "choo" written "cho".', '{"question":"Andika neno lenye maana ya \"chumba cha kujisaidia\".","wrong_answer":"cho","correct_answer":"choo"}'::jsonb, 'The child hears the length but does not know it is shown by two letters.', 'The question "Andika neno lenye maana ya "chumba cha kujisaidia"." with "cho" among the options.', 'Clap the two vowels as two beats; compare a word with one and two vowels.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T7_KUANDIKA_MANENO_IPAS.TAHAJIA.M1_TAH_NGAPOS_T7', 'KISW.G1.KUANDI.T7_KUANDIKA_MANENO_IPAS.TAHAJIA', 'Writes ng'' without the apostrophe (ngombe for ng''ombe), or puts it where it does not belong (ng''oma for ngoma).', '{"question":"Ni tahajia ipi sahihi ya mnyama anayetupa maziwa?","wrong_answer":"ngombe","correct_answer":"ng''ombe"}'::jsonb, 'Ng'' and ng are two sounds; the apostrophe looks like dirt on the page to the child.', 'The question "Ni tahajia ipi sahihi ya mnyama anayetupa maziwa?" with "ngombe" among the options.', 'Say ng''ombe and ngoma: the first has no g sound; mark it with the apostrophe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T7_KUANDIKA_MANENO_IPAS.TAHAJIA.M1_TAH_JOIN_T7', 'KISW.G1.KUANDI.T7_KUANDIKA_MANENO_IPAS.TAHAJIA', 'Joins two words into one, or splits one word into two (kwasababu; mwana funzi).', '{"question":"Ni lipi sahihi?","wrong_answer":"Nilichelewa kwasababu ya mvua.","correct_answer":"Nilichelewa kwa sababu ya mvua."}'::jsonb, 'In speech the words run together; the child has not seen each written apart.', 'The question "Ni lipi sahihi?" with "Nilichelewa kwasababu ya mvua." among the options.', 'Count the words aloud with a finger for each before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T7_UKANUSHAJI.UKANUSHAJI.M1_SAR_FINALA_T7', 'KISW.G1.SARUFI.T7_UKANUSHAJI.UKANUSHAJI', 'Keeps the final -a in the negative present (hasoma for hasomi).', '{"question":"Kanusha: Mimi ninaoga.","wrong_answer":"Mimi sioga.","correct_answer":"Mimi siogi."}'::jsonb, 'The child adds the negative prefix and leaves the rest of the verb as it was.', 'The question "Kanusha: Mimi ninaoga." with "Mimi sioga." among the options.', 'Show the pair with the end of the verb circled: anasoma - hasomi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T7_UKANUSHAJI.UKANUSHAJI.M1_SAR_KEEPNA_T7', 'KISW.G1.SARUFI.T7_UKANUSHAJI.UKANUSHAJI', 'Keeps the tense marker -na- in the negative (hanasomi for hasomi).', '{"question":"Kanusha: Mimi ninaosha mikono.","wrong_answer":"Mimi sinaoshi mikono.","correct_answer":"Mimi sioshi mikono."}'::jsonb, 'The child negates by adding ha- to the whole positive verb.', 'The question "Kanusha: Mimi ninaosha mikono." with "Mimi sinaoshi mikono." among the options.', 'Cross out na in the positive form and change the end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T7_UKANUSHAJI.UKANUSHAJI.M1_SAR_SIPLUS_T7', 'KISW.G1.SARUFI.T7_UKANUSHAJI.UKANUSHAJI', 'Negates by putting si before the positive verb (Yeye si anasoma).', '{"question":"Kanusha: Sisi tunachana nywele.","wrong_answer":"Sisi si tunachana nywele.","correct_answer":"Sisi hatuchani nywele."}'::jsonb, 'Si is the negative the child knows (si mimi), so he puts it in front of any sentence.', 'The question "Kanusha: Sisi tunachana nywele." with "Sisi si tunachana nywele." among the options.', 'Show si as the negative of ni (Yeye si mwalimu) and ha- as the negative of a verb.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T7_UKANUSHAJI.UKANUSHAJI.M1_SAR_PERSNEG_T7', 'KISW.G1.SARUFI.T7_UKANUSHAJI.UKANUSHAJI', 'Uses the negative prefix of another person (Wao hasomi for hawasomi; Mimi hasomi for sisomi).', '{"question":"Kanusha: Sisi tunasugua meno.","wrong_answer":"Sisi hasugui meno.","correct_answer":"Sisi hatusugui meno."}'::jsonb, 'The child learnt one negative form (ha-) and uses it for all persons.', 'The question "Kanusha: Sisi tunasugua meno." with "Sisi hasugui meno." among the options.', 'Table of persons: si-, hu-, ha-, hatu-, ham-, hawa-; the child points before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI.M1_SAU_NEAR_T8', 'KISW.G1.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI', 'Says /f/ for /v/, so "viazi" becomes "fiazi".', '{"question":"Mwalimu anasema \"viazi\". Neno lipi limetamkwa vizuri?","wrong_answer":"fiazi","correct_answer":"viazi"}'::jsonb, 'Many Kenyan first languages have no /v/, or do not separate it from /f/; the child puts in the home sound.', 'The question "Mwalimu anasema "viazi". Neno lipi limetamkwa vizuri?" with "fiazi" among the options.', 'Say the two side by side, slowly, watching the mouth; the child holds up a card for the sound he hears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI.M1_SAU_NEAR2_T8', 'KISW.G1.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI', 'Says /s/ for /sh/, so "shamba" becomes "samba".', '{"question":"Neno lipi limetamkwa vizuri?","wrong_answer":"samba","correct_answer":"shamba"}'::jsonb, '/sh/ and /s/ are close; a first language with only one of them puts that one in both places.', 'The question "Neno lipi limetamkwa vizuri?" with "samba" among the options.', 'Contrast the two with a mirror and a hand before the mouth; the child says which he hears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI.M1_SAU_SYLL_T8', 'KISW.G1.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI', 'Splits "viazi" by letters rather than by syllables (each Kiswahili syllable ends in a vowel).', '{"question":"Neno \"viazi\" lina silabi zipi?","wrong_answer":"v-i-a-z-i","correct_answer":"vi-a-zi"}'::jsonb, 'The child has learnt letters one by one and has not been shown that a syllable is a sound that ends in a vowel.', 'The question "Neno "viazi" lina silabi zipi?" with "v-i-a-z-i" among the options.', 'Clap the word: one clap per vowel; the consonants go with the vowel after them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI.M1_SAU_NAME_T8', 'KISW.G1.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI', 'Says the English letter name instead of the Kiswahili sound (/j/ as "jei"), so the syllable cannot be built.', '{"question":"Sauti ya herufi \"j\" ni ipi?","wrong_answer":"jei","correct_answer":"/j/"}'::jsonb, 'English letter names are taught alongside and the child brings them to Kiswahili; a syllable is built from sounds, not names.', 'The question "Sauti ya herufi "j" ni ipi?" with "jei" among the options.', 'Say the sound alone, short (/j/), then join it to a vowel: ja, je, ji.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI.M1_SAU_PICK_T8', 'KISW.G1.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI', 'Picks a word with no target sound when asked for one that has it.', '{"question":"Ni neno lipi lina sauti /j/, /r/, /p/, /f/, /v/, /sh/?","wrong_answer":"ugali","correct_answer":"papai"}'::jsonb, 'The child looks at the first letter or the picture, not at the sound.', 'The question "Ni neno lipi lina sauti /j/, /r/, /p/, /f/, /v/, /sh/?" with "ugali" among the options.', 'Underline the target sound in each word on the card before choosing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M1_UFS_SOUND_T8', 'KISW.G1.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads the target word wrongly: "viazi" as "fiazi".', '{"question":"Neno \"viazi\" linasomwa vipi?","wrong_answer":"fiazi","correct_answer":"viazi"}'::jsonb, 'The child reads the letters with the sounds of his first language, or adds a vowel to break the cluster.', 'The question "Neno "viazi" linasomwa vipi?" with "fiazi" among the options.', 'Pick out the target words before reading; practise them on cards, then read the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M1_UFS_WORD_T8', 'KISW.G1.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Tunakula viazi na papai.\"?","wrong_answer":"Tunakula ... viazi ... na ... papai.","correct_answer":"Tunakula viazi na papai."}'::jsonb, 'The child is still decoding each word; he has not yet read a group of words as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Tunakula viazi na papai."?" with "Tunakula ... viazi ... na ... papai." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it in one breath.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M1_UFS_QUIET_T8', 'KISW.G1.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads so softly (or so loudly, shouting) that the class cannot follow.', '{"question":"Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?","wrong_answer":"ya chini ili nisikosee mbele ya wenzangu","correct_answer":"ya kusikika na wote darasani, bila kupiga kelele"}'::jsonb, 'Shyness, or the belief that reading well means reading loud.', 'The question "Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?" with "ya chini ili nisikosee mbele ya wenzangu" among the options.', 'Stand the reader at the front and a listener at the back: the listener raises a hand when he hears every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M1_UFS_PACE_T8', 'KISW.G1.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Kasi ifaayo ya kusoma kifungu ni ipi?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, karibu maneno 25 kwa dakika"}'::jsonb, 'Reading races in class reward speed; nobody asked whether the listeners understood.', 'The question "Kasi ifaayo ya kusoma kifungu ni ipi?" with "haraka iwezekanavyo" among the options.', 'Time two readings, one very fast and one at speaking pace; the listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M1_UFS_MARK_T8', 'KISW.G1.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question in the flat voice of a statement and runs on through the koma and kikomo.', '{"question":"Sentensi \"Je, umekunywa uji?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the marks.', 'The question "Sentensi "Je, umekunywa uji?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that fits each reading; clap at each kikomo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T8_TAHAJIA.TAHAJIA.M1_TAH_MT_T8', 'KISW.G1.KUANDI.T8_TAHAJIA.TAHAJIA', 'Spells the word with the sound of his first language: "mchele" written "mchere".', '{"question":"Ni tahajia ipi sahihi?","wrong_answer":"mchere","correct_answer":"mchele"}'::jsonb, 'The child writes as he says the word; if his first language merges the two sounds, the letter is a guess.', 'The question "Ni tahajia ipi sahihi?" with "mchere" among the options.', 'Keep a list of the class''s hard pairs (l/r, s/sh, z/dh, s/th); say each word slowly before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T8_TAHAJIA.TAHAJIA.M1_TAH_NASAL_T8', 'KISW.G1.KUANDI.T8_TAHAJIA.TAHAJIA', 'Drops the nasal: "ndizi" written "dizi".', '{"question":"Ni tahajia ipi sahihi?","wrong_answer":"dizi","correct_answer":"ndizi"}'::jsonb, 'The n or m before a consonant is soft and quick; the child does not hear it.', 'The question "Ni tahajia ipi sahihi?" with "dizi" among the options.', 'Hum the nasal before the word (mmm-bwa, nnn-dege).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T8_TAHAJIA.TAHAJIA.M1_TAH_VOWEL_T8', 'KISW.G1.KUANDI.T8_TAHAJIA.TAHAJIA', 'Writes a long vowel short, so the word changes: "mkaa" written "mka".', '{"question":"Andika neno lenye maana ya \"kitu kinachochomwa kupikia\".","wrong_answer":"mka","correct_answer":"mkaa"}'::jsonb, 'The child hears the length but does not know it is shown by two letters.', 'The question "Andika neno lenye maana ya "kitu kinachochomwa kupikia"." with "mka" among the options.', 'Clap the two vowels as two beats; compare a word with one and two vowels.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T8_TAHAJIA.TAHAJIA.M1_TAH_NGAPOS_T8', 'KISW.G1.KUANDI.T8_TAHAJIA.TAHAJIA', 'Writes ng'' without the apostrophe (ngombe for ng''ombe), or puts it where it does not belong (ng''oma for ngoma).', '{"question":"Ni tahajia ipi sahihi ya mnyama anayetupa maziwa?","wrong_answer":"ngombe","correct_answer":"ng''ombe"}'::jsonb, 'Ng'' and ng are two sounds; the apostrophe looks like dirt on the page to the child.', 'The question "Ni tahajia ipi sahihi ya mnyama anayetupa maziwa?" with "ngombe" among the options.', 'Say ng''ombe and ngoma: the first has no g sound; mark it with the apostrophe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T8_TAHAJIA.TAHAJIA.M1_TAH_JOIN_T8', 'KISW.G1.KUANDI.T8_TAHAJIA.TAHAJIA', 'Joins two words into one, or splits one word into two (kwasababu; mwana funzi).', '{"question":"Ni lipi sahihi?","wrong_answer":"Nilichelewa kwasababu ya mvua.","correct_answer":"Nilichelewa kwa sababu ya mvua."}'::jsonb, 'In speech the words run together; the child has not seen each written apart.', 'The question "Ni lipi sahihi?" with "Nilichelewa kwasababu ya mvua." among the options.', 'Count the words aloud with a finger for each before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T8_MATUMIZI_YA_HIKI_NA_.VIONYESHI.M1_SAR_CLASSDEM_T8', 'KISW.G1.SARUFI.T8_MATUMIZI_YA_HIKI_NA_.VIONYESHI', 'Uses the people word (huyu, yule) for a thing (kiti huyu).', '{"question":"Jaza: Chakula ___ ni kitamu.","wrong_answer":"huyu","correct_answer":"hiki"}'::jsonb, 'Huyu was the first pointing word learnt; the child uses it for anything.', 'The question "Jaza: Chakula ___ ni kitamu." with "huyu" among the options.', 'Point at a child (huyu) and at a chair (hiki); then sort pictures by the pointing word they take.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T8_MATUMIZI_YA_HIKI_NA_.VIONYESHI.M1_SAR_NUMDEM_T8', 'KISW.G1.SARUFI.T8_MATUMIZI_YA_HIKI_NA_.VIONYESHI', 'Uses the one-thing pointing word with a plural noun (watoto huyu).', '{"question":"Jaza: Vyakula ___ ni vitamu.","wrong_answer":"hiki","correct_answer":"hivi"}'::jsonb, 'The child changes the noun but not the pointing word.', 'The question "Jaza: Vyakula ___ ni vitamu." with "hiki" among the options.', 'Pair the forms on cards: huyu-hawa, yule-wale, hiki-hivi, hili-haya.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T8_MATUMIZI_YA_HIKI_NA_.VIONYESHI.M1_SAR_HII_T8', 'KISW.G1.SARUFI.T8_MATUMIZI_YA_HIKI_NA_.VIONYESHI', 'Uses hii for every noun (kitabu hii, mtoto hii), as in town Kiswahili.', '{"question":"Jaza: Kikombe ___ ni changu.","wrong_answer":"hii","correct_answer":"hiki"}'::jsonb, 'Hii is the pointing word heard most in town speech, where the noun class is dropped.', 'The question "Jaza: Kikombe ___ ni changu." with "hii" among the options.', 'Read pairs aloud: kitabu hiki, mtoto huyu, nyumba hii; the child hears the match.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T8_MATUMIZI_YA_HIKI_NA_.VIONYESHI.M1_SAR_REVERSE_T8', 'KISW.G1.SARUFI.T8_MATUMIZI_YA_HIKI_NA_.VIONYESHI', 'Takes the plural form for the singular (miti for one tree, vitabu for one book).', '{"question":"Ni kipi ni umoja?","wrong_answer":"viazi hivi","correct_answer":"kiazi hiki"}'::jsonb, 'The child heard the plural more often (a tree is usually among trees) and learnt it as the name.', 'The question "Ni kipi ni umoja?" with "viazi hivi" among the options.', 'Hold one object, then many; the child names each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T9_MAZUNGUMZO.MAZUNGUMZO.M1_MAZ_TOPIC_T9', 'KISW.G1.KUSIKI.T9_MAZUNGUMZO.MAZUNGUMZO', 'Says something that has nothing to do with the topic.', '{"question":"Mnazungumza kuhusu vyombo vya jikoni. Ni sentensi ipi inafaa?","wrong_answer":"Jana nilitazama katuni nzuri.","correct_answer":"Mama ana jokofu jikoni."}'::jsonb, 'The child says what is on his mind; he has not learnt that a conversation has a topic everyone keeps to.', 'The question "Mnazungumza kuhusu vyombo vya jikoni. Ni sentensi ipi inafaa?" with "Jana nilitazama katuni nzuri." among the options.', 'Put the topic picture in the middle; before speaking the child points to it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T9_MAZUNGUMZO.MAZUNGUMZO.M1_MAZ_TURN_T9', 'KISW.G1.KUSIKI.T9_MAZUNGUMZO.MAZUNGUMZO', 'Talks over others and does not wait for his turn.', '{"question":"Mwenzako anazungumza. Unafanya nini?","wrong_answer":"ninaanza kuzungumza pia","correct_answer":"ninasikiliza mpaka amalize, kisha ninazungumza"}'::jsonb, 'Eagerness: the child fears he will forget his idea.', 'The question "Mwenzako anazungumza. Unafanya nini?" with "ninaanza kuzungumza pia" among the options.', 'Pass a talking object (a ball): only the one holding it speaks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T9_MAZUNGUMZO.MAZUNGUMZO.M1_MAZ_MIX_T9', 'KISW.G1.KUSIKI.T9_MAZUNGUMZO.MAZUNGUMZO', 'Mixes English or Sheng words into the Kiswahili sentence.', '{"question":"Sema kwa Kiswahili sanifu:","wrong_answer":"Mama ana fridge jikoni.","correct_answer":"Mama ana jokofu jikoni."}'::jsonb, 'At home and in town the child hears mixed speech and does not know the Kiswahili word.', 'The question "Sema kwa Kiswahili sanifu:" with "Mama ana fridge jikoni." among the options.', 'Keep a word wall: the English or Sheng word, and its Kiswahili word next to it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T9_MAZUNGUMZO.MAZUNGUMZO.M1_MAZ_GEST_T9', 'KISW.G1.KUSIKI.T9_MAZUNGUMZO.MAZUNGUMZO', 'Uses a gesture or face that does not match the words (smiling while giving sad news).', '{"question":"Unasema \"Rafiki yangu ni mgonjwa.\" Uso wako unaonyesha nini?","wrong_answer":"tabasamu kubwa","correct_answer":"huzuni"}'::jsonb, 'The child smiles from shyness or does not link the face to the message.', 'The question "Unasema "Rafiki yangu ni mgonjwa." Uso wako unaonyesha nini?" with "tabasamu kubwa" among the options.', 'Say one sentence with three faces; the class picks the face that fits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T9_MAZUNGUMZO.MAZUNGUMZO.M1_MAZ_LR_T9', 'KISW.G1.KUSIKI.T9_MAZUNGUMZO.MAZUNGUMZO', 'Says /l/ for /r/ (or /r/ for /l/) while speaking: "rafiki" becomes "lafiki".', '{"question":"Tamka vizuri: rafiki","wrong_answer":"lafiki","correct_answer":"rafiki"}'::jsonb, 'Several Kenyan first languages do not separate /l/ and /r/; the home sound carries into Kiswahili.', 'The question "Tamka vizuri: rafiki" with "lafiki" among the options.', 'Practise the pairs with a mirror: the tongue taps for r, it rests for l.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU.M1_UFM_WORD_T9', 'KISW.G1.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Gives "sufuria" the meaning of a word that looks or sounds like it.', '{"question":"Soma: \"Mama yuko jikoni. Anapika ugali na sukumawiki. Dada anaosha sufuria. Chakula kiko tayari.\" Neno \"sufuria\" lina maana gani?","wrong_answer":"sufu","correct_answer":"chombo cha kupikia"}'::jsonb, 'The child matches the word to a known one by its look instead of reading the sentence around it.', 'The question "Soma: "Mama yuko jikoni. Anapika ugali na sukumawiki. Dada anaosha sufuria. Chakula kiko tayari." Neno "sufuria" lina maana gani?" with "sufu" among the options.', 'Cover the word; the child says what word would fit the sentence, then uncovers it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU.M1_UFM_MSG_T9', 'KISW.G1.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Gives one detail of the passage as its message.', '{"question":"Ujumbe wa kifungu ni upi?","wrong_answer":"Dada anaosha sufuria.","correct_answer":"Familia hushirikiana kupika chakula."}'::jsonb, 'The detail is what the child remembers best; he has not been asked what the writer wants us to know.', 'The question "Ujumbe wa kifungu ni upi?" with "Dada anaosha sufuria." among the options.', 'Ask two questions side by side: "Nini kilitokea?" and "Kifungu kinatuambia nini?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU.M1_UFM_GUESS_T9', 'KISW.G1.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Predicts something the passage gives no clue for, without looking at the picture.', '{"question":"Picha inaonyesha meza yenye sahani. Familia itafanya nini?","wrong_answer":"Italala.","correct_answer":"Itakula chakula pamoja."}'::jsonb, 'Prediction is taken as free imagination; the child has not been shown that clues in the text and picture point the way.', 'The question "Picha inaonyesha meza yenye sahani. Familia itafanya nini?" with "Italala." among the options.', 'Underline the clue words and point at the picture; the guess must fit them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU.M1_UFM_LESSON_T9', 'KISW.G1.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Retells what happened when asked for the lesson.', '{"question":"Tunajifunza nini kutokana na kifungu?","wrong_answer":"Mama anapika ugali.","correct_answer":"Tunapaswa kuwasaidia wazazi kazi za jikoni."}'::jsonb, 'The lesson question sounds like a what-happened question to the child.', 'The question "Tunajifunza nini kutokana na kifungu?" with "Mama anapika ugali." among the options.', 'Start the answer with "Tunajifunza kwamba tunapaswa..."', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU.M1_UFM_OWN_T9', 'KISW.G1.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Answers from his own life instead of from the passage.', '{"question":"Mama anapika nini?","wrong_answer":"Mama yangu anapika wali.","correct_answer":"ugali na sukumawiki"}'::jsonb, 'The child links the question to what he knows from home and does not check the text.', 'The question "Mama anapika nini?" with "Mama yangu anapika wali." among the options.', 'Ask the child to point at the line in the passage that gives the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T9_KIFUNGU_KUTOKANA_NA_.KIFUNGU.M1_INS_NAME_T9', 'KISW.G1.KUANDI.T9_KIFUNGU_KUTOKANA_NA_.KIFUNGU', 'Lists the things in the picture (mti, mtoto, mbwa) instead of writing sentences about what is happening.', '{"question":"Ni kipi ni kifungu kuhusu picha?","wrong_answer":"mti. mtoto. mbwa.","correct_answer":"Mtoto anacheza na mbwa chini ya mti."}'::jsonb, 'Naming pictures was the earlier task; the child has not moved to sentences.', 'The question "Ni kipi ni kifungu kuhusu picha?" with "mti. mtoto. mbwa." among the options.', 'Ask "Nani? Anafanya nini? Wapi?" for each part of the picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T9_KIFUNGU_KUTOKANA_NA_.KIFUNGU.M1_INS_TITLE_T9', 'KISW.G1.KUANDI.T9_KIFUNGU_KUTOKANA_NA_.KIFUNGU', 'Writes no title, or a title that does not fit the writing.', '{"question":"Kichwa kipi kinafaa insha kuhusu jikoni?","wrong_answer":"Insha","correct_answer":"Jikoni Kwetu"}'::jsonb, 'The child thinks the word "insha" or the date is the title.', 'The question "Kichwa kipi kinafaa insha kuhusu jikoni?" with "Insha" among the options.', 'Read the finished writing and ask: what is it about in three words?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T9_KIFUNGU_KUTOKANA_NA_.KIFUNGU.M1_INS_HALAFU_T9', 'KISW.G1.KUANDI.T9_KIFUNGU_KUTOKANA_NA_.KIFUNGU', 'Joins every sentence with "na halafu", so the writing is one long sentence.', '{"question":"Ni lipi limeandikwa vizuri?","wrong_answer":"Tuliamka na halafu tukaoga na halafu tukaenda sokoni.","correct_answer":"Tuliamka asubuhi. Tulioga, kisha tukaenda sokoni."}'::jsonb, 'Spoken retelling joins events with na halafu; the child writes as he talks.', 'The question "Ni lipi limeandikwa vizuri?" with "Tuliamka na halafu tukaoga na halafu tukaenda sokoni." among the options.', 'Give a word bank: kwanza, kisha, baadaye, mwishowe; one per sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T9_KIFUNGU_KUTOKANA_NA_.KIFUNGU.M1_INS_TENSE_T9', 'KISW.G1.KUANDI.T9_KIFUNGU_KUTOKANA_NA_.KIFUNGU', 'Slips from one tense to another in the middle of the writing (past -li- to present -na-, or habitual hu- to past).', '{"question":"Ni lipi sahihi?","wrong_answer":"Mama alipika ugali. Dada anaosha vyombo.","correct_answer":"Mama alipika ugali. Dada aliosha vyombo."}'::jsonb, 'The child thinks of the events as he writes and the tense of the moment comes in.', 'The question "Ni lipi sahihi?" with "Mama alipika ugali. Dada anaosha vyombo." among the options.', 'Underline every verb; all the tense markers should match.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T9_KIFUNGU_KUTOKANA_NA_.KIFUNGU.M1_INS_MIX_T9', 'KISW.G1.KUANDI.T9_KIFUNGU_KUTOKANA_NA_.KIFUNGU', 'Puts English or Sheng words into the Kiswahili writing.', '{"question":"Sahihisha:","wrong_answer":"Mama anapika rice.","correct_answer":"Mama anapika wali."}'::jsonb, 'The child does not know the Kiswahili word and fills the gap with the one he knows.', 'The question "Sahihisha:" with "Mama anapika rice." among the options.', 'Keep a word bank of theme words on the board before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T9_MATUMIZI_YA_MANENO_Y.VITENDO.M1_SAR_VNOUN_T9', 'KISW.G1.SARUFI.T9_MATUMIZI_YA_MANENO_Y.VITENDO', 'Picks a thing word as the action word (in "Mama anapika ugali" chooses ugali).', '{"question":"Neno la kitendo katika \"Mama anapika ugali\" ni lipi?","wrong_answer":"ugali","correct_answer":"anapika"}'::jsonb, 'The child looks for the word he knows best, often the thing he can picture.', 'The question "Neno la kitendo katika "Mama anapika ugali" ni lipi?" with "ugali" among the options.', 'Act the sentence: the word you can do is the action word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T9_MATUMIZI_YA_MANENO_Y.VITENDO.M1_SAR_VBARE_T9', 'KISW.G1.SARUFI.T9_MATUMIZI_YA_MANENO_Y.VITENDO', 'Writes the bare verb with no person marker (Mama pika ugali for Mama anapika ugali).', '{"question":"Ni lipi sahihi?","wrong_answer":"Mama pika ugali.","correct_answer":"Mama anapika ugali."}'::jsonb, 'The command form (pika!) is heard most at home and the child uses it in every sentence.', 'The question "Ni lipi sahihi?" with "Mama pika ugali." among the options.', 'Colour the a-na- in front of the verb; read the sentence with and without it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T9_MATUMIZI_YA_MANENO_Y.VITENDO.M1_SAR_VAGREE_T9', 'KISW.G1.SARUFI.T9_MATUMIZI_YA_MANENO_Y.VITENDO', 'Gives the verb the marker of the wrong person or number (Mama wanapika; Watoto anacheza).', '{"question":"Jaza: Watoto ___ (kula) chakula.","wrong_answer":"anakula","correct_answer":"wanakula"}'::jsonb, 'The child has not linked the start of the verb to who is doing it.', 'The question "Jaza: Watoto ___ (kula) chakula." with "anakula" among the options.', 'Point at the doer, then at the start of the verb; they must match (mmoja a-, wengi wa-).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T9_MATUMIZI_YA_MANENO_Y.VITENDO.M1_SAR_VADJ_T9', 'KISW.G1.SARUFI.T9_MATUMIZI_YA_MANENO_Y.VITENDO', 'Takes a describing word for an action word (in "Sahani ni safi" chooses safi as the action).', '{"question":"Neno la kitendo katika \"Dada anaosha sahani safi\" ni lipi?","wrong_answer":"safi","correct_answer":"anaosha"}'::jsonb, 'Any word after the noun looks like what the noun "does".', 'The question "Neno la kitendo katika "Dada anaosha sahani safi" ni lipi?" with "safi" among the options.', 'Ask "Inafanya nini?" If there is no answer, there is no action word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI.M1_SAU_NEAR_T10', 'KISW.G1.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI', 'Says /z/ for /dh/, so "dhahabu" becomes "zahabu".', '{"question":"Mwalimu anasema \"dhahabu\". Neno lipi limetamkwa vizuri?","wrong_answer":"zahabu","correct_answer":"dhahabu"}'::jsonb, 'Many Kenyan first languages have no /dh/, or do not separate it from /z/; the child puts in the home sound.', 'The question "Mwalimu anasema "dhahabu". Neno lipi limetamkwa vizuri?" with "zahabu" among the options.', 'Say the two side by side, slowly, watching the mouth; the child holds up a card for the sound he hears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI.M1_SAU_NEAR2_T10', 'KISW.G1.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI', 'Says /sh/ for /ch/, so "chenga" becomes "shenga".', '{"question":"Neno lipi limetamkwa vizuri?","wrong_answer":"shenga","correct_answer":"chenga"}'::jsonb, '/ch/ and /sh/ are close; a first language with only one of them puts that one in both places.', 'The question "Neno lipi limetamkwa vizuri?" with "shenga" among the options.', 'Contrast the two with a mirror and a hand before the mouth; the child says which he hears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI.M1_SAU_DROP_T10', 'KISW.G1.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI', 'Drops part of the target sound, so "ngoma" becomes "goma".', '{"question":"Neno \"ngoma\" limeandikwa au kutamkwa vipi kwa usahihi?","wrong_answer":"goma","correct_answer":"ngoma"}'::jsonb, 'The second part of the sound (the w or y glide, or the soft nasal) is quick and quiet; the child does not hear it and leaves it out.', 'The question "Neno "ngoma" limeandikwa au kutamkwa vipi kwa usahihi?" with "goma" among the options.', 'Stretch the syllable slowly (p-y-a), then say it fast; the child copies.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI.M1_SAU_SYLL_T10', 'KISW.G1.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI', 'Splits "ngoma" by letters rather than by syllables (each Kiswahili syllable ends in a vowel).', '{"question":"Neno \"ngoma\" lina silabi zipi?","wrong_answer":"n-g-o-m-a","correct_answer":"ngo-ma"}'::jsonb, 'The child has learnt letters one by one and has not been shown that a syllable is a sound that ends in a vowel.', 'The question "Neno "ngoma" lina silabi zipi?" with "n-g-o-m-a" among the options.', 'Clap the word: one clap per vowel; the consonants go with the vowel after them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI.M1_SAU_PICK_T10', 'KISW.G1.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI', 'Picks a word with no target sound when asked for one that has it.', '{"question":"Ni neno lipi lina sauti /ny/, /dh/, /th/, /ch/, /gh/, /ng/, /ng''/?","wrong_answer":"mpira","correct_answer":"chenga"}'::jsonb, 'The child looks at the first letter or the picture, not at the sound.', 'The question "Ni neno lipi lina sauti /ny/, /dh/, /th/, /ch/, /gh/, /ng/, /ng''/?" with "mpira" among the options.', 'Underline the target sound in each word on the card before choosing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M1_UFS_SOUND_T10', 'KISW.G1.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads the target word wrongly: "chenga" as "shenga".', '{"question":"Neno \"chenga\" linasomwa vipi?","wrong_answer":"shenga","correct_answer":"chenga"}'::jsonb, 'The child reads the letters with the sounds of his first language, or adds a vowel to break the cluster.', 'The question "Neno "chenga" linasomwa vipi?" with "shenga" among the options.', 'Pick out the target words before reading; practise them on cards, then read the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M1_UFS_WORD_T10', 'KISW.G1.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Tunacheza ngoma uwanjani.\"?","wrong_answer":"Tunacheza ... ngoma ... uwanjani.","correct_answer":"Tunacheza ngoma uwanjani."}'::jsonb, 'The child is still decoding each word; he has not yet read a group of words as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Tunacheza ngoma uwanjani."?" with "Tunacheza ... ngoma ... uwanjani." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it in one breath.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M1_UFS_QUIET_T10', 'KISW.G1.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads so softly (or so loudly, shouting) that the class cannot follow.', '{"question":"Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?","wrong_answer":"ya chini ili nisikosee mbele ya wenzangu","correct_answer":"ya kusikika na wote darasani, bila kupiga kelele"}'::jsonb, 'Shyness, or the belief that reading well means reading loud.', 'The question "Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?" with "ya chini ili nisikosee mbele ya wenzangu" among the options.', 'Stand the reader at the front and a listener at the back: the listener raises a hand when he hears every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M1_UFS_PACE_T10', 'KISW.G1.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Kasi ifaayo ya kusoma kifungu ni ipi?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, karibu maneno 30 kwa dakika"}'::jsonb, 'Reading races in class reward speed; nobody asked whether the listeners understood.', 'The question "Kasi ifaayo ya kusoma kifungu ni ipi?" with "haraka iwezekanavyo" among the options.', 'Time two readings, one very fast and one at speaking pace; the listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M1_UFS_MARK_T10', 'KISW.G1.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question in the flat voice of a statement and runs on through the koma and kikomo.', '{"question":"Sentensi \"Je, umeona nyota?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the marks.', 'The question "Sentensi "Je, umeona nyota?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that fits each reading; clap at each kikomo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T10_KIFUNGU_KUTOKANA_NA_.KIFUNGU.M1_INS_NAME_T10', 'KISW.G1.KUANDI.T10_KIFUNGU_KUTOKANA_NA_.KIFUNGU', 'Lists the things in the picture (mti, mtoto, mbwa) instead of writing sentences about what is happening.', '{"question":"Ni kipi ni kifungu kuhusu picha?","wrong_answer":"mti. mtoto. mbwa.","correct_answer":"Mtoto anacheza na mbwa chini ya mti."}'::jsonb, 'Naming pictures was the earlier task; the child has not moved to sentences.', 'The question "Ni kipi ni kifungu kuhusu picha?" with "mti. mtoto. mbwa." among the options.', 'Ask "Nani? Anafanya nini? Wapi?" for each part of the picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T10_KIFUNGU_KUTOKANA_NA_.KIFUNGU.M1_INS_TITLE_T10', 'KISW.G1.KUANDI.T10_KIFUNGU_KUTOKANA_NA_.KIFUNGU', 'Writes no title, or a title that does not fit the writing.', '{"question":"Kichwa kipi kinafaa insha kuhusu michezo?","wrong_answer":"Insha","correct_answer":"Michezo Shuleni"}'::jsonb, 'The child thinks the word "insha" or the date is the title.', 'The question "Kichwa kipi kinafaa insha kuhusu michezo?" with "Insha" among the options.', 'Read the finished writing and ask: what is it about in three words?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T10_KIFUNGU_KUTOKANA_NA_.KIFUNGU.M1_INS_HALAFU_T10', 'KISW.G1.KUANDI.T10_KIFUNGU_KUTOKANA_NA_.KIFUNGU', 'Joins every sentence with "na halafu", so the writing is one long sentence.', '{"question":"Ni lipi limeandikwa vizuri?","wrong_answer":"Tuliamka na halafu tukaoga na halafu tukaenda sokoni.","correct_answer":"Tuliamka asubuhi. Tulioga, kisha tukaenda sokoni."}'::jsonb, 'Spoken retelling joins events with na halafu; the child writes as he talks.', 'The question "Ni lipi limeandikwa vizuri?" with "Tuliamka na halafu tukaoga na halafu tukaenda sokoni." among the options.', 'Give a word bank: kwanza, kisha, baadaye, mwishowe; one per sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T10_KIFUNGU_KUTOKANA_NA_.KIFUNGU.M1_INS_TENSE_T10', 'KISW.G1.KUANDI.T10_KIFUNGU_KUTOKANA_NA_.KIFUNGU', 'Slips from one tense to another in the middle of the writing (past -li- to present -na-, or habitual hu- to past).', '{"question":"Ni lipi sahihi?","wrong_answer":"Jana tulicheza mpira. Juma anafunga bao.","correct_answer":"Jana tulicheza mpira. Juma alifunga bao."}'::jsonb, 'The child thinks of the events as he writes and the tense of the moment comes in.', 'The question "Ni lipi sahihi?" with "Jana tulicheza mpira. Juma anafunga bao." among the options.', 'Underline every verb; all the tense markers should match.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.KUANDI.T10_KIFUNGU_KUTOKANA_NA_.KIFUNGU.M1_INS_MIX_T10', 'KISW.G1.KUANDI.T10_KIFUNGU_KUTOKANA_NA_.KIFUNGU', 'Puts English or Sheng words into the Kiswahili writing.', '{"question":"Sahihisha:","wrong_answer":"Tulicheza football.","correct_answer":"Tulicheza mpira wa miguu."}'::jsonb, 'The child does not know the Kiswahili word and fills the gap with the one he knows.', 'The question "Sahihisha:" with "Tulicheza football." among the options.', 'Keep a word bank of theme words on the board before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME.M1_SAR_NEGATE_T10', 'KISW.G1.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME', 'Gives the negative of the verb (hafungui) instead of its opposite action (funga).', '{"question":"Kinyume cha \"anza\" (mchezo) ni?","wrong_answer":"usianze","correct_answer":"maliza"}'::jsonb, 'The child thinks "opposite" means "not doing it".', 'The question "Kinyume cha "anza" (mchezo) ni?" with "usianze" among the options.', 'Act it: fungua the door, then funga it; not doing anything is not the opposite.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME.M1_SAR_ADDUA_T10', 'KISW.G1.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME', 'Makes an opposite by adding -ua to any verb (keti -> ketua).', '{"question":"Kinyume cha \"keti\" ni?","wrong_answer":"ketua","correct_answer":"simama"}'::jsonb, 'Fungua/funga and vaa/vua show a pattern, and the child uses it everywhere.', 'The question "Kinyume cha "keti" ni?" with "ketua" among the options.', 'Sort pairs into two piles: made with -ua (funga-fungua) and different words (keti-simama).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME.M1_SAR_SAME_T10', 'KISW.G1.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME', 'Gives a word of the same meaning as the opposite (simama - inuka).', '{"question":"Kinyume cha \"ingia\" ni?","wrong_answer":"jiunga","correct_answer":"toka"}'::jsonb, 'The child knows the words go together but not that they mean the same.', 'The question "Kinyume cha "ingia" ni?" with "jiunga" among the options.', 'Act both words: if the action is the same, it is not the opposite.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G1.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME.M1_SAR_NOUNOPP_T10', 'KISW.G1.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME', 'Gives a place or thing word as the opposite of an action (ingia - nje).', '{"question":"Kinyume cha \"panda\" (mti) ni?","wrong_answer":"chini","correct_answer":"shuka"}'::jsonb, 'Ingia and nje are heard together in "ingia ndani, toka nje".', 'The question "Kinyume cha "panda" (mti) ni?" with "chini" among the options.', 'Ask "Ni kitendo?" before accepting: the opposite of an action is an action.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
